INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE', 'ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL', 'english', 7, 'Use polite expressions to introduce yourself and others', ARRAY['ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.a', 'ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.b']::text[], 'Chooses the polite way to introduce yourself, a friend or a visitor (May I introduce my friend, Wanjiru? Pleased to meet you), puts the person of honour first, and spots a rude or blunt turn, in 8 of 10 new items.', '["choose the polite expression","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN', 'english', 7, 'Choose a text that suits a purpose: fiction, non-fiction and independent reading', ARRAY['ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.a', 'ENGL.G7.READIN.T9_GRADE_APPROPRIATE_FI.a', 'ENGL.G7.READIN.T11_EXTENSIVE_READING_NO.a']::text[], 'Chooses the book or text that fits what the reader needs (information, enjoyment, a topic, a level), tells fiction from non-fiction, and does not choose by the cover, the length or the title alone, in 8 of 10 new items.', '["choose the book for a purpose","fiction or non-fiction","judge the relevance of a text"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN', 'english', 7, 'Read selected fiction and non-fiction independently', ARRAY['ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.b', 'ENGL.G7.READIN.T9_GRADE_APPROPRIATE_FI.b', 'ENGL.G7.READIN.T11_EXTENSIVE_READING_NO.b']::text[], 'The child reads selected fiction and non-fiction alone over the term, keeps a reading log with one line on what each was about, and tells a classmate why it is worth reading. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["reading log","book talk","recommend a book"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS', 'english', 7, 'Tell common, proper, collective and abstract nouns apart', ARRAY['ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.a', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.b']::text[], 'Names a noun as common (river), proper (Mombasa), collective (a flock of birds) or abstract (courage), picks the collective noun that goes with a group (a swarm of bees), and writes a capital letter for a proper noun only, in 8 of 10 new items.', '["choose the kind of noun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER', 'ENGL.G7.READIN.T1_INTENSIVE_READING_TR', 'english', 7, 'Know trickster narratives and the lessons they teach', ARRAY['ENGL.G7.READIN.T1_INTENSIVE_READING_TR.a', 'ENGL.G7.READIN.T1_INTENSIVE_READING_TR.b']::text[], 'Says that a trickster is a clever character who gets what it wants by a trick (Hare, Spider), names the trick and who is fooled, and says what the story teaches, and does not call the trickster a hero or the fooled one a trickster, in 8 of 10 new items.', '["choose the trickster","choose the trick or the lesson","choose what the trickster is like"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI', 'english', 7, 'Describe the features of legible and neat handwriting', ARRAY['ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.a']::text[], 'Names the features of neat handwriting (letters of an even size that sit on the line, tall and short letters kept distinct, clear spaces between words, a steady slant) and says why it matters, and does not take fast, decorated or crowded writing for neat, in 8 of 10 new items.', '["choose the feature","choose what to work on"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI', 'english', 7, 'Write texts legibly and neatly', ARRAY['ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.b']::text[], 'The child writes a page with letters of even size and slant, clear spaces between words, straight margins, no crowding at the line end and no crossings-out in the fair copy. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["write a fair copy","copy the paragraph neatly","rewrite this page neatly"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O', 'english', 7, 'Know the techniques of telling an oral narrative', ARRAY['ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.a']::text[], 'Names how a good storyteller uses the voice (loud and soft, fast and slow), pauses, gestures, face, eye contact and audience participation, and picks the technique that fits a part of a story, in 8 of 10 new items.', '["choose the technique","choose the best way to tell this part"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O', 'english', 7, 'Perform oral narratives, poems, lullabies and praise songs with the right techniques', ARRAY['ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.b', 'ENGL.G7.READIN.T2_INTENSIVE_READING_SI.b', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.c', 'ENGL.G7.READIN.T6_ORAL_LITERATURE_SONG.b', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.c']::text[], 'The child performs an oral narrative, poem, lullaby or praise song with voice changes, pauses, gestures, eye contact and audience participation that fit it, and can say the key message it carries. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["perform the narrative","recite the poem","sing the lullaby and say its message"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS', 'english', 7, 'Use count and non-count nouns: many, much, a few, a little', ARRAY['ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.a', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.b']::text[], 'Tells a count noun (chair, chairs) from a non-count noun (water, advice), uses many and a few with count nouns and much and a little with non-count nouns, and does not write advices, informations or furnitures, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS', 'english', 7, 'Form singular and plural nouns correctly', ARRAY['ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.a', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.b']::text[], 'Writes the plural of nouns with the usual -s or -es, -ies after a consonant and y (baby, babies), -ves (knife, knives), the irregular plurals (child, children; man, men; tooth, teeth) and the nouns that do not change (sheep), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL', 'english', 7, 'Use the parts of a book to preview it', ARRAY['ENGL.G7.READIN.T2_INTENSIVE_READING_CL.a']::text[], 'Says what the cover, title page, blurb, contents page, author''s note and glossary tell the reader and which part to read first to decide on a book, and does not mix them up, in 8 of 10 new items.', '["choose the part for the need","choose what the part tells you"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL', 'english', 7, 'Describe the author and the setting of a class reader', ARRAY['ENGL.G7.READIN.T2_INTENSIVE_READING_CL.b']::text[], 'From the cover, the title page, the blurb and the first chapter, the child names the author and describes the setting in time and place, quoting the clues. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who wrote it","where and when is it set","which clues show the setting"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING', 'english', 7, 'Use the full stop, question mark and exclamation mark', ARRAY['ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.a', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.b']::text[], 'Ends a statement with a full stop, a question with a question mark and a strong feeling or command with an exclamation mark, and does not use a question mark after a reported question, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake","choose the mark"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING', 'ENGL.G7.READIN.T3_READING_INFORMATION_', 'english', 7, 'Tell reading for information from reading for meaning', ARRAY['ENGL.G7.READIN.T3_READING_INFORMATION_.a']::text[], 'Says that reading for information is to find facts (a timetable, a notice) and reading for meaning is to understand and enjoy what the writer says (a story, a poem), and chooses which to do for a task, in 8 of 10 new items.', '["information or meaning","choose the way to read for the task"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE', 'english', 7, 'Use regular and irregular verbs in the past and the past participle', ARRAY['ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.a', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.b']::text[], 'Writes the past form (went, saw, ate) and the past participle (gone, seen, eaten) of common irregular verbs, tells them from regular verbs that add -ed, and does not write goed, seen for saw or have went, in 8 of 10 new items.', '["choose the correct form","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE', 'english', 7, 'Choose the present, past or future tense from the time in the sentence', ARRAY['ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.b']::text[], 'Uses the time word (every day, yesterday, next week) to choose the present, past or future form, and does not write yesterday I go or tomorrow I went, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["reasoning","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO', 'english', 7, 'Describe the structure of a poem: line, stanza, rhyme and refrain', ARRAY['ENGL.G7.READIN.T3_INTENSIVE_READING_PO.a', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.b', 'ENGL.G7.READIN.T2_INTENSIVE_READING_SI.a', 'ENGL.G7.READIN.T6_ORAL_LITERATURE_SONG.a']::text[], 'Counts the lines and the stanzas of a poem, finds the words that rhyme by sound (not spelling), the line or words that repeat (the refrain), and tells a poem from a story by its shape, in 8 of 10 new items.', '["poem or prose","choose the rhyming words","choose the repeated line","count the stanzas"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA', 'english', 7, 'Know the parts of a narrative paragraph', ARRAY['ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.a']::text[], 'Names the parts of a narrative paragraph (the opening that sets the scene, the events in order, the closing) and tells which sentence plays which part, and which does not belong, in 8 of 10 new items.', '["choose the opening sentence","find the part","put the sentences in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA', 'english', 7, 'Compose a well-developed narrative paragraph using examples and incidents', ARRAY['ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.b', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.b']::text[], 'The child writes a paragraph with a topic sentence, events or supporting sentences in order with an example or an incident, and a closing sentence. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a paragraph about","add an example","add an incident"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS', 'english', 7, 'Tell specific from general information and pick out the details', ARRAY['ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.a', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.b', 'ENGL.G7.LISTEN.T3_LISTENING_FOR_THE_MA.b', 'ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.a']::text[], 'Says whether a question asks for the general idea or for a specific detail (a name, a number, a place, a time), and picks out the specific detail from a short text read to or by the learner, in 8 of 10 new items.', '["general or specific","choose the specific detail","type the specific detail"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS', 'english', 7, 'Listen attentively to a text or song and respond to its key issues', ARRAY['ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.c', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.a', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.b']::text[], 'After listening to a talk or song (on leadership, land travel), the child names the key issues raised, gives specific details, and responds with a fitting comment, question or action. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["what issue did the song raise","respond to the speaker","what would you advise"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'ENGL.G7.READIN.T4_INTENSIVE_READING', 'english', 7, 'Choose a reading strategy for a purpose: skimming, scanning, predicting, rereading', ARRAY['ENGL.G7.READIN.T4_INTENSIVE_READING.a']::text[], 'Chooses skimming for a quick idea of a text, scanning for a name or number, predicting from the title and clues, and rereading with the words around a hard sentence, and names the strategy from what the reader does, in 8 of 10 new items.', '["choose the strategy for the purpose","name the strategy"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE', 'english', 7, 'Write the simple present tense', ARRAY['ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.a', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.b']::text[], 'Writes the simple present for habits and facts, adds -s or -es after he, she, it or one name (She walks, he washes), uses do not and does not with the plain verb, and does not write he walk or she do not know, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE', 'english', 7, 'Write the simple past tense', ARRAY['ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.a', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.c']::text[], 'Writes the simple past with -ed (with the spelling changes stopped, studied) or the irregular form, uses did not and did with the plain verb, and does not write did not went or she walkd, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL', 'english', 7, 'Name the main and minor characters and what each does in a story', ARRAY['ENGL.G7.READIN.T4_INTENSIVE_READING_CL.a', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.b', 'ENGL.G7.READIN.T7_CHARACTERS_IN_CLASS_.a', 'ENGL.G7.READIN.T7_CHARACTERS_IN_CLASS_.b', 'ENGL.G7.READIN.T10_CHARACTERS_AND_THEIR.a', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL.a']::text[], 'Names the main character (the story is about the person) and a minor character (helps or gets in the way) from a short story, and says what the character does to move the story on, in 8 of 10 new items.', '["choose the main character","choose a minor character","choose the role"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL', 'english', 7, 'Judge a character from what the person says and does', ARRAY['ENGL.G7.READIN.T4_INTENSIVE_READING_CL.b', 'ENGL.G7.READIN.T10_CHARACTERS_AND_THEIR.b', 'ENGL.G7.READIN.T8_INTENSIVE_READING_PO.b', 'ENGL.G7.READIN.T12_INTENSIVE_READING_CO.c', 'ENGL.G7.LISTEN.T8_LISTENING_COMPREHENS.a', 'ENGL.G7.READIN.T8_INTENSIVE_READING_PO.a']::text[], 'Chooses the trait that a character''s words and actions support (brave, selfish, honest, jealous), and the line that is the evidence, and does not judge from the name or one word, in 8 of 10 new items.', '["choose the trait","choose the evidence"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL', 'english', 7, 'Predict what happens next from the title and the clues', ARRAY['ENGL.G7.READIN.T4_INTENSIVE_READING_CL.c']::text[], 'Uses the title and the clues so far to choose the most likely next event and says which clue supports it, in 8 of 10 new passages.', '["choose the best prediction","choose the clue that supports it"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E', 'english', 7, 'Support a paragraph with examples and incidents', ARRAY['ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.a']::text[], 'Chooses the example or incident that supports the topic sentence, tells it from a sentence that is off the topic, and says which words introduce an example (for example, for instance), in 8 of 10 new items.', '["choose the supporting example","find the sentence that does not belong"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS', 'english', 7, 'Articulate the consonant and vowel sounds clearly in words and sentences', ARRAY['ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.b', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.b']::text[], 'The child articulates the Grade 7 target sounds (/t/ and /d/, /l/ and /r/, /ʊ/ and /uː/, /f/ and /v/, /n/ and /ŋ/) so that tin and din, light and right, pull and pool, sin and sing are heard as different words. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read the pairs aloud","say the sentence clearly"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS', 'english', 7, 'Use stress to pronounce words correctly and tell their meanings apart', ARRAY['ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.c', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.c', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.d']::text[], 'The child says CONtract (noun) and conTRACT (verb), PROgress and proGRESS, and stresses longer words correctly (eLECtion, not elecTION). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say it as a noun and as a verb","which syllable is strong","what does the stress change"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE', 'english', 7, 'Use comparative and superlative adjectives', ARRAY['ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.a', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.b']::text[], 'Writes -er and -est for short adjectives, more and most for long ones, the irregular forms (good, better, best; bad, worse, worst), than with the comparative and the with the superlative, and does not write more taller or the most best, in 8 of 10 new items.', '["pick the form","fill the gap","spot the mistake","choose the correct word"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR', 'english', 7, 'Name the hero of a legend and the lesson a story teaches', ARRAY['ENGL.G7.READIN.T5_INTENSIVE_READING_OR.a', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.b', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI.c', 'ENGL.G7.READIN.T12_CLASS_READER_MAIN_ID.b', 'ENGL.G7.LISTEN.T8_LISTENING_COMPREHENS.c']::text[], 'Says what makes a character a hero in a legend (brave, wise, generous), and chooses the moral lesson of a story, not a detail and not a lesson the story does not teach, in 8 of 10 new items.', '["choose the heroic quality","choose the lesson"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR', 'english', 7, 'Relate characters, lessons and events in texts to real life', ARRAY['ENGL.G7.READIN.T5_INTENSIVE_READING_OR.c', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.d', 'ENGL.G7.READIN.T8_INTENSIVE_READING.c', 'ENGL.G7.READIN.T10_CHARACTERS_AND_THEIR.c', 'ENGL.G7.READIN.T12_CLASS_READER_MAIN_ID.c']::text[], 'The child links a character, a lesson or an event in a legend, poem or class reader to a real person, situation or choice in his or her life or community, and says why the story matters there. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["who is like this in your community","how does this lesson help you","why do people tell this story"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F', 'english', 7, 'Know the parts of a friendly letter', ARRAY['ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.a']::text[], 'Puts the writer''s address, date, greeting, body, closing (Your friend) and name in their places, and does not use the closing of a formal letter or write the receiver''s address in a friendly letter, in 8 of 10 new items.', '["choose the part and its place","choose the closing","find the mistake in a letter"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F', 'english', 7, 'Compose a friendly letter in the correct format', ARRAY['ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.b']::text[], 'The child writes a friendly letter with the address and date, a warm greeting, paragraphs of news, a fitting closing and the name, in a friendly but correct tone. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a letter to","reply to this letter","correct the letter"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS', 'english', 7, 'Interrupt politely and take turns', ARRAY['ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.a', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.c']::text[], 'Chooses the polite way to interrupt (Excuse me, may I say something?), to wait for a turn and to give one, tells it from a rude way, and says which gestures show politeness, in 8 of 10 new items.', '["choose the polite interruption","verbal or non-verbal","fill the gap"]'::jsonb, '["reasoning","recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS', 'english', 7, 'Apply turn-taking skills in different speaking contexts', ARRAY['ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.b']::text[], 'In a pair or group talk the child waits for a pause, keeps the turn short, links to what was said, and invites others in by name or with a question. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["hold a group discussion","keep the conversation going","hand the turn on"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'ENGL.G7.READIN.T6_READING_FLUENCY', 'english', 7, 'Read a text at the right speed, accurately and with expression', ARRAY['ENGL.G7.READIN.T6_READING_FLUENCY.b', 'ENGL.G7.READIN.T15_READING_FLUENCY.b']::text[], 'The child reads a Grade 7 text aloud at a steady speaking pace, in phrases, with few slips, and uses the voice to show punctuation, speech and feeling. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read the dialogue in parts","reread for expression"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS', 'english', 7, 'Tell adverbs of time, place and manner apart', ARRAY['ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.a']::text[], 'Says whether an adverb tells when (yesterday, soon), where (here, outside) or how (slowly, carefully) an action happens, and does not name an adjective as an adverb, in 8 of 10 new items.', '["choose the kind of adverb","find the adverb","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS', 'english', 7, 'Use adverbs of time, place and manner in sentences', ARRAY['ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.b']::text[], 'Writes the adverb of manner (quickly, well, hard), keeps the same form for fast, hard and late, does not write good for well or hardly for hard, and puts the adverb where it makes the meaning clear, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO', 'english', 7, 'Spell commonly misspelt words', ARRAY['ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.a', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.b']::text[], 'Spells words that often go wrong (because, friend, believe, beautiful, address, definitely, parliament, necessary, calendar, February) and picks the correct spelling from three that look alike, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES', 'ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS', 'english', 7, 'Take detailed notes while listening', ARRAY['ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.b']::text[], 'While listening to a talk on forests, the child writes key words and numbers under headings, not whole sentences, and catches the details the speaker signals (first, the main reason, for example). Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["make notes as you listen","complete the note frame","check your notes against the talk"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS', 'ENGL.G7.READIN.T7_INDEPENDENT_READING_', 'english', 7, 'Read a table, a chart or a map for information', ARRAY['ENGL.G7.READIN.T7_INDEPENDENT_READING_.a', 'ENGL.G7.READIN.T7_INDEPENDENT_READING_.b']::text[], 'Says what kind of information a table, a bar graph, a pie chart, a map, a diagram and a timeline give, and reads a fact from a small table or chart, and does not read a row for a column, in 8 of 10 new items.', '["choose the visual for the need","read the table"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS', 'english', 7, 'Use personal pronouns: I and me, he and him, we and us', ARRAY['ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.a', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.b']::text[], 'Uses the subject form (I, he, she, we, they) before a verb and the object form (me, him, her, us, them) after a verb or preposition, and does not write me and him went or between you and I, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS', 'english', 7, 'Use possessive pronouns and possessive adjectives: mine, my, its', ARRAY['ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.a', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.b', 'ENGL.G7.GRAMMA.T10_DETERMINERS.a', 'ENGL.G7.GRAMMA.T10_DETERMINERS.b']::text[], 'Tells a possessive adjective before a noun (my book) from a possessive pronoun that stands alone (the book is mine), writes its (belonging) and it''s (it is) correctly, and does not write her''s or your''s, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT', 'english', 7, 'Put the steps of the writing process in order', ARRAY['ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.a']::text[], 'Names the steps (planning, drafting, revising, editing, publishing), says what is done at each and puts them in order, and does not edit before the draft is written, in 8 of 10 new items.', '["choose the step","put the steps in order","what is done at this step"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT', 'english', 7, 'Write and self-assess narrative compositions through the writing process', ARRAY['ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.b', 'ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.b', 'ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.b', 'ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.b']::text[], 'The child plans, drafts, revises, edits and writes a fair copy of a narrative with a clear introduction, a body that builds and a conclusion, uses idioms that fit, and assesses each part against a checklist. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["plan, draft and revise a story","assess your introduction, body and conclusion","use the idioms in a story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS', 'ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS', 'english', 7, 'Use simple prepositions of time, place and direction', ARRAY['ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.a', 'ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.b']::text[], 'Says whether a preposition shows time (at, on, in), place (beside, under) or direction (to, into, across), chooses at, on or in for times and places, and does not write at Monday or in the morning of Friday, in 8 of 10 new items.', '["choose the kind of preposition","choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE', 'ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_', 'english', 7, 'Know the steps of assessing a narrative composition', ARRAY['ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.a']::text[], 'Says which part of a narrative to check for what (the introduction for who, where and when, the body for events in order, the conclusion for how it ends), and the first step of an assessment (reading it again slowly), and finds the part that needs work, in 8 of 10 new items.', '["choose the part to check","find what needs work"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON', 'english', 7, 'Choose words by the vowel sounds /ʊ/ and /uː/', ARRAY['ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.b', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.a']::text[], 'Picks the word with the short sound of put (/ʊ/) or the long sound of food (/uː/), and does not match words by spelling (look and food both have oo), in 8 of 10 new items.', '["pick the word with the same sound","find the odd one out"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC', 'ENGL.G7.GRAMMA.T9_CONJUNCTIONS', 'english', 7, 'Join words and sentences with and, but and or', ARRAY['ENGL.G7.GRAMMA.T9_CONJUNCTIONS.a', 'ENGL.G7.GRAMMA.T9_CONJUNCTIONS.b']::text[], 'Uses and to add, but to show a difference and or to give a choice, and does not write but and or two joining words together, or a comma where and is needed, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["reasoning","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL', 'english', 7, 'Put the events of a story in order', ARRAY['ENGL.G7.READIN.T9_INTENSIVE_READING_CL.a', 'ENGL.G7.LISTEN.T8_LISTENING_COMPREHENS.b', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL.b']::text[], 'Puts four events of a story in the order they happened, using time words such as first, then, after and finally, in 8 of 10 new passages.', '["put the events in order","choose the first event","choose the last event"]'::jsonb, '["procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES', 'ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR', 'english', 7, 'Know the features of a narrative composition', ARRAY['ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.a']::text[], 'Names the features of a narrative (a title, characters, a setting, a problem, events in order, a ending), tells a narrative from a description or a letter, and finds the part that is missing, in 8 of 10 new items.', '["choose the feature","narrative or other text","find what is missing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES', 'ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D', 'english', 7, 'Know the occasions and features of a speech', ARRAY['ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.a', 'ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.b']::text[], 'Names the occasions for a speech (a wedding, a funeral, a school assembly, a prize day), the parts of a speech (greeting, introduction, body, conclusion, thanks) and the features of a good delivery, in 8 of 10 new items.', '["choose the occasion","choose the part of a speech","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA', 'english', 7, 'Make notes: main and supporting points', ARRAY['ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.a', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.b', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.c']::text[], 'Tells a main point from a supporting point, and chooses the notes that keep the main points in a few words (not whole sentences and not only a detail), in 8 of 10 new texts.', '["choose the main point","choose the best notes"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'ENGL.G7.GRAMMA.T10_DETERMINERS', 'english', 7, 'Use the articles a, an and the', ARRAY['ENGL.G7.GRAMMA.T10_DETERMINERS.a', 'ENGL.G7.GRAMMA.T10_DETERMINERS.b']::text[], 'Chooses a before a consonant sound (a university), an before a vowel sound (an hour, an egg), and the for one named or known thing, and does not use a before a vowel sound or the before a general idea, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P', 'english', 7, 'Group items in a packing or shopping list', ARRAY['ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.a']::text[], 'Puts items under the heading they belong to (food, clothes, tools, stationery), finds the item that does not belong in a group, and chooses the list that fits the event, in 8 of 10 new items.', '["choose the heading","find the odd item","choose the list for the event"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P', 'english', 7, 'Write a packing list and a shopping list for a given purpose', ARRAY['ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.b', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.c']::text[], 'The child writes a list with a heading, items grouped (clothes, food, documents), quantities where needed, and only what the event or purpose calls for. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a packing list for","prepare a shopping list for","group the items"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW', 'ENGL.G7.LISTEN.T11_INTERVIEWS', 'english', 7, 'Know the reasons and the manners of an interview', ARRAY['ENGL.G7.LISTEN.T11_INTERVIEWS.a']::text[], 'Names why a person sits an interview (a school place, a scholarship, a job), chooses the confident and polite answer, asks for clarification politely (Could you repeat the question?), and spots a poor answer, in 8 of 10 new items.', '["choose the reason","choose the best answer","ask for clarification"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK', 'ENGL.G7.LISTEN.T11_INTERVIEWS', 'english', 7, 'Speak clearly and confidently in an interview and seek clarification', ARRAY['ENGL.G7.LISTEN.T11_INTERVIEWS.b', 'ENGL.G7.LISTEN.T11_INTERVIEWS.c', 'ENGL.G7.LISTEN.T11_INTERVIEWS.d']::text[], 'The child greets the panel, answers each question in full with a reason or example, speaks clearly and confidently but humbly, and asks politely for a question to be repeated or explained. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["role play an interview","answer the panel''s questions","ask the panel to repeat a question"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION', 'ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI', 'english', 7, 'Form adjectives from nouns and verbs', ARRAY['ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.a', 'ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.b']::text[], 'Forms the adjective from a noun or verb with -ful, -less, -y, -ous, -al, -ive or -able (care, careful; danger, dangerous; create, creative), and keeps the spelling right (beauty, beautiful), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI', 'english', 7, 'Know a dilemma narrative and its closing formula', ARRAY['ENGL.G7.READIN.T11_INTENSIVE_READING_DI.a', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI.b']::text[], 'Says that a dilemma narrative ends with a hard choice put to the listener (Who was right? What would you have done?), picks the closing question, and tells it from a narrative that ends with a lesson, in 8 of 10 new items.', '["choose the closing formula","choose the dilemma","dilemma or other story"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY', 'english', 7, 'Choose and spell synonyms and antonyms', ARRAY['ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.x1', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.x2', 'ENGL.G7.READIN.T5_SYNONYMS_AND_ANTONYM.a', 'ENGL.G7.READIN.T5_SYNONYMS_AND_ANTONYM.b', 'ENGL.G7.READIN.T5_SYNONYMS_AND_ANTONYM.c']::text[], 'Chooses and writes a word with the same meaning (synonym) or the opposite meaning (antonym) in a sentence, spells it correctly, and does not give a word that is related but not the same, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY', 'english', 7, 'Write numbers in words and spell them correctly', ARRAY['ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.x1', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.x2']::text[], 'Spells numbers in words (fourteen, forty, ninety, eighth), writes ordinals with the right ending (1st, 2nd, 3rd, 4th, 21st) and puts the hyphen in twenty-one to ninety-nine, in 8 of 10 new items.', '["choose the correct spelling","choose the correct sentence","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES', 'ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN', 'english', 7, 'Use expressions that give a view or an opinion', ARRAY['ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.a', 'ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.b']::text[], 'Chooses the expression that shows a view (In my opinion, I believe, I feel that, As I see it), tells a view from a fact, and agrees or disagrees politely (I see your point, but ...), in 8 of 10 new items.', '["choose the opinion expression","view or fact","fill the gap"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS', 'english', 7, 'Use phrasal verbs with put, come and give', ARRAY['ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.a', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.b']::text[], 'Gives the meaning of put on, put off, put out, come across, come up with, give up, give in and give away from the sentence, and picks the right particle, not a word that only looks like it, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake","choose the correct word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_', 'english', 7, 'Know the format of a written dialogue', ARRAY['ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.a']::text[], 'Puts the speaker''s name, a colon and the words spoken on a new line for each turn, writes actions in brackets, and does not use quotation marks round every line of a play-style dialogue, in 8 of 10 new items.', '["choose the dialogue format","find the mistake in a dialogue"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_', 'english', 7, 'Write a dialogue through the writing process', ARRAY['ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.b']::text[], 'The child writes a dialogue with each speaker''s name on the left, a colon, the words on the same line with no quotation marks, a new line for each speaker and actions in brackets. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a dialogue between","set out the dialogue","revise the dialogue"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS', 'english', 7, 'Use words about land travel', ARRAY['ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.c']::text[], 'Chooses the right word (passenger, fare, route, junction, conductor, terminus, luggage, timetable, journey, destination) to complete a sentence about travel, and does not mix a person with a place or a thing, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO', 'english', 7, 'Find the key idea of a passage', ARRAY['ENGL.G7.READIN.T13_INTENSIVE_READING_CO.a', 'ENGL.G7.READIN.T4_INTENSIVE_READING.b', 'ENGL.G7.READIN.T12_INTENSIVE_READING_CO.a', 'ENGL.G7.READIN.T12_CLASS_READER_MAIN_ID.a', 'ENGL.G7.READIN.T14_STUDY_SKILLS_SUMMARI.a', 'ENGL.G7.LISTEN.T3_LISTENING_FOR_THE_MA.a', 'ENGL.G7.READIN.T8_INTENSIVE_READING.a']::text[], 'Chooses the sentence or title that covers the whole passage, tells it from a detail, and finds a specific detail asked for, in 8 of 10 new passages.', '["choose the main idea","choose the best title","find the specific detail"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO', 'english', 7, 'Summarise a passage', ARRAY['ENGL.G7.READIN.T13_INTENSIVE_READING_CO.b', 'ENGL.G7.READIN.T14_STUDY_SKILLS_SUMMARI.b', 'ENGL.G7.READIN.T8_INTENSIVE_READING.d']::text[], 'Chooses the short account that has the key ideas in the right order, and does not choose one that is a single detail, a copy of the first lines or that adds something the passage does not say, in 8 of 10 new passages.', '["choose the best summary","choose what the summary leaves out"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO', 'english', 7, 'Make mental images from a passage', ARRAY['ENGL.G7.READIN.T13_INTENSIVE_READING_CO.c']::text[], 'Picks the words of a passage that make a picture, says what the writer wants the reader to see, hear or feel, and does not pick the line that only gives a fact, in 8 of 10 new passages.', '["choose the line that paints a picture","choose what the picture shows"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO', 'english', 7, 'Deduce the meaning of words from context', ARRAY['ENGL.G7.READIN.T13_INTENSIVE_READING_CO.d', 'ENGL.G7.READIN.T3_READING_INFORMATION_.b', 'ENGL.G7.READIN.T8_INTENSIVE_READING.b', 'ENGL.G7.READIN.T12_INTENSIVE_READING_CO.b']::text[], 'Uses the words around an unfamiliar word to choose its meaning and says which words gave the clue, in 8 of 10 new passages.', '["choose the meaning","choose the clue words"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO', 'english', 7, 'Answer factual questions from a passage', ARRAY['ENGL.G7.READIN.T13_INTENSIVE_READING_CO.e', 'ENGL.G7.READIN.T8_INTENSIVE_READING.e', 'ENGL.G7.READIN.T4_INTENSIVE_READING.b']::text[], 'Finds an answer that is stated in the passage, tells true from false and not stated, and does not pick a detail that sits near the answer, in 8 of 10 new passages.', '["short comprehension: choose","true, false or not stated","short comprehension: type"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO', 'english', 7, 'Answer inferential questions from a passage', ARRAY['ENGL.G7.READIN.T13_INTENSIVE_READING_CO.e', 'ENGL.G7.READIN.T8_INTENSIVE_READING.e', 'ENGL.G7.READIN.T12_INTENSIVE_READING_CO.c']::text[], 'Works out what the passage does not say outright (why a character acts, how a person feels) and does not give an answer the passage contradicts or merely repeats, in 8 of 10 new passages.', '["short comprehension: choose","stated or worked out"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE', 'ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN', 'english', 7, 'Tell a simple sentence from a fragment and write one', ARRAY['ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.a', 'ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.b']::text[], 'Says that a simple sentence has one subject and one verb and tells a complete thought, tells it from a fragment that has no verb or no subject, and from two sentences joined without a joining word, in 8 of 10 new items.', '["choose the simple sentence","spot the mistake","choose the complete sentence"]'::jsonb, '["rule","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI', 'english', 7, 'Know the purpose and features of a praise song', ARRAY['ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.a', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.b']::text[], 'Says that a praise song honours a person (a chief, a runner, a bride) on an occasion, uses praise names and exaggeration, and tells the singer from the one praised, in 8 of 10 new items.', '["choose the purpose or occasion","choose the praise line","who is who"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS', 'ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR', 'english', 7, 'Explain the meaning of idioms in context', ARRAY['ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.a']::text[], 'Gives the meaning of an idiom from its sentence (it is raining cats and dogs, spill the beans, a piece of cake, hit the nail on the head), and does not read it word for word, in 8 of 10 new items.', '["choose the meaning","choose the idiom for the situation","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND', 'english', 7, 'Choose words by the consonant sounds /t/, /d/, /l/, /r/, /v/, /f/, /n/ and /ŋ/', ARRAY['ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.a', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.a', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.a']::text[], 'Picks the word that starts or ends with the sound named, tells /f/ from /v/ (five, fiver) and /n/ from /ŋ/ (sin, sing), and does not match by spelling, in 8 of 10 new items.', '["pick the word with the same sound","find the odd one out"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND', 'english', 7, 'Use correct intonation for yes or no and WH questions', ARRAY['ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.c']::text[], 'The child lets the voice rise at the end of yes or no questions (Did you score?) and fall at the end of WH questions (Who scored?), in varied situations. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["up or down at the end","say the question","turn the statement into a question"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME', 'english', 7, 'Find the subject and the verb and make them agree', ARRAY['ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.a', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.b']::text[], 'Finds the subject and the verb of a sentence, makes the verb agree with a singular or plural subject (The boys play, the boy plays), and does not let a noun near the verb decide the agreement (The box of mangoes is heavy), in 8 of 10 new items.', '["find the subject","choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE', 'ENGL.G7.READIN.T14_FEATURES_OF_STYLE', 'english', 7, 'Find dialogue, similes and metaphors in a text and use them', ARRAY['ENGL.G7.READIN.T14_FEATURES_OF_STYLE.a', 'ENGL.G7.READIN.T14_FEATURES_OF_STYLE.b']::text[], 'Says that dialogue is the words characters speak, a simile compares with like or as and a metaphor says one thing is another, picks each from a short text, and completes a simile or a metaphor, in 8 of 10 new items.', '["simile or metaphor or dialogue","fill the gap","choose the correct word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_', 'english', 7, 'Know the features of descriptive writing', ARRAY['ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.a']::text[], 'Names what makes writing descriptive (the five senses, adjectives and adverbs, similes, an order such as top to bottom), tells a description from a narrative, and picks the sentence with the best detail, in 8 of 10 new items.', '["choose the descriptive sentence","description or narrative","choose the order"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_', 'english', 7, 'Write a descriptive composition of 200 to 240 words', ARRAY['ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.b']::text[], 'The child describes one person, thing or place in 200 to 240 words, through the senses and with similes and exact words, in a clear order, with an introduction and a conclusion. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["describe a place","describe a person","describe a match"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT', 'ENGL.G7.LISTEN.T15_ORAL_REPORTS', 'english', 7, 'Know how an oral report of an event is organised', ARRAY['ENGL.G7.LISTEN.T15_ORAL_REPORTS.a', 'ENGL.G7.LISTEN.T15_ORAL_REPORTS.b']::text[], 'Puts the parts of an oral report in order (greeting, what happened, who, when and where, the end), and picks the sentence that opens or closes a report, in 8 of 10 new items.', '["choose the part","put the parts in order","choose the opening or closing"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES', 'ENGL.G7.READIN.T15_READING_FLUENCY', 'english', 7, 'Recognise the strategies of reading fluently', ARRAY['ENGL.G7.READIN.T15_READING_FLUENCY.a', 'ENGL.G7.READIN.T6_READING_FLUENCY.a']::text[], 'Names how a fluent reader reads (the right speed, a changing voice for feelings, a short pause at a comma and a longer one at a full stop, words read in groups, a text read again) and tells a fluent reader from one who reads flat, too fast or word by word, in 8 of 10 new items.', '["choose the fluency strategy","which reader is fluent"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA', 'english', 7, 'Write affirmative and negative sentences', ARRAY['ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.a', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.b']::text[], 'Tells an affirmative sentence from a negative one, makes a sentence negative with do not, does not, did not, is not or cannot, and does not write a double negative (I do not have no pen), in 8 of 10 new items.', '["choose the negative sentence","choose the correct word","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.READIN.T15_POETRY.POEM_MEANING', 'ENGL.G7.READIN.T15_POETRY', 'english', 7, 'Say what a poem is about and what it teaches', ARRAY['ENGL.G7.READIN.T15_POETRY.a', 'ENGL.G7.READIN.T15_POETRY.b', 'ENGL.G7.READIN.T8_INTENSIVE_READING.a', 'ENGL.G7.READIN.T8_INTENSIVE_READING.e']::text[], 'Chooses the subject of a poem (what it is about), the message the poet wants to pass on, and the idea in a line, and does not choose a detail as the subject or an idea the poem does not hold, in 8 of 10 new items.', '["choose the subject","choose the message","choose what the line means"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N', 'english', 7, 'Know the format of a notice and a poster', ARRAY['ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.a']::text[], 'Names the parts of a notice (heading, what, when, where, who to see, the writer and the date) and of a poster (a big heading, a few words, a picture, the details), and finds the part that is missing, in 8 of 10 new items.', '["choose the part","find what is missing","notice or poster"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N', 'english', 7, 'Design notices and posters on current issues', ARRAY['ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.b']::text[], 'The child designs a notice (heading, what, when, where, who to contact, signed and dated) or a poster (big heading, few words, a picture, clear call to action) on a current issue. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["design a notice for","design a poster on","improve this poster"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
