INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE.M7_IP_BLUNT', 'ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE', 'Introduces a person bluntly (This is Wanjiru. Shake.).', '{"question":"Which is the polite way to introduce your friend to the headteacher.","wrong_answer":"This is my friend. He is Juma.","correct_answer":"Madam, may I introduce my friend, Juma?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "This is my friend. He is Juma." next to the right answer in a new sentence and ask again.', 'A polite introduction asks permission and uses a title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE.M7_IP_ORDER', 'ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE', 'Introduces the older or senior person to the younger one, not the other way round.', '{"question":"Whom do you name first when introducing your friend to the headteacher.","wrong_answer":"your friend","correct_answer":"the headteacher"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "your friend" next to the right answer in a new sentence and ask again.', 'The person of higher rank is named first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE.M7_IP_REPLY', 'ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE', 'Replies with no polite words after an introduction (Okay.).', '{"question":"You are introduced to a visitor. Which reply is polite.","wrong_answer":"Okay.","correct_answer":"Pleased to meet you, sir."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Okay." next to the right answer in a new sentence and ask again.', 'Greet and show you are glad to meet the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE.M7_IP_SELF', 'ENGL.G7.LISTEN.T1_CONVERSATIONAL_SKILL.INTRO_POLITE', 'Introduces self without a name or with a rude opening (Me, I am Otieno).', '{"question":"Which is the best way to introduce yourself at a new school.","wrong_answer":"Me, I am Otieno.","correct_answer":"Good morning. My name is Otieno, and I am in Grade 7."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Me, I am Otieno." next to the right answer in a new sentence and ask again.', 'Greet, give your name and one useful detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT.M7_SX_BY_COVER', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT', 'Chooses a book by its cover or its length alone.', '{"question":"You need facts about Kenyan birds. Which book do you choose.","wrong_answer":"the book with the nicest cover","correct_answer":"a book called A Guide to the Birds of Kenya"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the book with the nicest cover" next to the right answer in a new sentence and ask again.', 'Choose by the topic and purpose, not the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT.M7_SX_FICTION_NON', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT', 'Mixes up fiction and non-fiction.', '{"question":"Which is a non-fiction text.","wrong_answer":"a story about a talking hare","correct_answer":"a book about how rain forms"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a story about a talking hare" next to the right answer in a new sentence and ask again.', 'Non-fiction gives facts about real things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT.M7_SX_LEVEL', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT', 'Chooses a book that is too hard or too easy for the reader.', '{"question":"Which book suits a Grade 7 learner reading for fun on a weekend.","wrong_answer":"a picture book for a Grade 1 child","correct_answer":"a short adventure novel for young teenagers"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a picture book for a Grade 1 child" next to the right answer in a new sentence and ask again.', 'A book should suit the reader''s age and interest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT.M7_SX_PURPOSE', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.SUITABLE_TEXT', 'Does not match the text to the purpose (a story for information).', '{"question":"You want to find out how a pump works. Which is the best text.","wrong_answer":"a poem about water","correct_answer":"an illustrated science book on pumps"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a poem about water" next to the right answer in a new sentence and ask again.', 'Information is found in non-fiction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M7_X_IR_ONE_KIND', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Reads only fiction or only one series.', '{"question":"Your log has only one series. What should you add?","wrong_answer":"the next book in the series","correct_answer":"a non-fiction book on a profession"}'::jsonb, 'Comfort reading.', 'Offer "the next book in the series" beside "a non-fiction book on a profession" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add a new kind of text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M7_X_IR_NO_LOG', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Keeps no record of reading.', '{"question":"How will you show what you read this term?","wrong_answer":"I will remember","correct_answer":"a reading log"}'::jsonb, 'Records feel like extra work.', 'Offer "I will remember" beside "a reading log" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One line after each text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M7_X_IR_BLURB_ONLY', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Logs a book after reading only the blurb.', '{"question":"Tell me how the book ends.","wrong_answer":"I only read the back.","correct_answer":"The heroine wins a scholarship."}'::jsonb, 'The aim becomes a full log.', 'Offer "I only read the back." beside "The heroine wins a scholarship." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the whole text before logging it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M7_X_IR_NO_REASON', 'ENGL.G7.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Cannot give a reason for recommending a book.', '{"question":"Why should I read it?","wrong_answer":"It is nice.","correct_answer":"It shows how a nurse saved a village; it is exciting."}'::jsonb, 'Opinion without reasons.', 'Offer "It is nice." beside "It shows how a nurse saved a village; it is exciting." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give one reason from the book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES.M7_NT_PROPER_SMALL', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'Writes a proper noun with a small letter (kisumu, december) or a common noun with a capital.', '{"question":"We go to ___ every December.","wrong_answer":"kisumu","correct_answer":"Kisumu"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "kisumu" next to the right answer in a new sentence and ask again.', 'Names of particular places, people, days and months start with a capital letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES.M7_NT_COLLECTIVE_WRONG', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'Uses the wrong collective noun for a group (a herd of birds, a swarm of cattle).', '{"question":"A ___ of bees settled on the tree.","wrong_answer":"herd","correct_answer":"swarm"}'::jsonb, 'Uses one word, such as group, or the word learnt first, for every group.', 'Offer "herd" next to the right answer in a new sentence and ask again.', 'Each group has its own word: a swarm of bees, a flock of birds, a herd of cattle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES.M7_NT_COLLECTIVE_PLURAL', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'Thinks a collective noun is always plural (the team are winning, a flocks of birds).', '{"question":"A ___ of birds flew over the school.","wrong_answer":"flocks","correct_answer":"flock"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "flocks" next to the right answer in a new sentence and ask again.', 'A collective noun names one group, so a flock is one thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES.M7_NT_ABSTRACT_COMMON', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'Calls an idea or feeling a common noun for things we can touch, or the other way round.', '{"question":"Which noun is abstract: bridge, courage, bottle, drum.","wrong_answer":"bridge","correct_answer":"courage"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "bridge" next to the right answer in a new sentence and ask again.', 'Ask: can I touch or see it? Courage is an idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES.M7_NT_COMMON_PROPER', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'Calls a name of a kind (river, city) a proper noun, or a particular name a common noun.', '{"question":"Which is a proper noun: city, Nairobi, river, teacher.","wrong_answer":"city","correct_answer":"Nairobi"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "city" next to the right answer in a new sentence and ask again.', 'A proper noun is the name of one particular place or person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES.M7_NT_COLLECTIVE_SINGLE', 'ENGL.G7.GRAMMA.T1_WORD_CLASSES_NOUNS.NOUN_TYPES', 'Takes one member of the group, or the person who looks after it, for the collective noun.', '{"question":"Which noun is a collective noun.","wrong_answer":"player","correct_answer":"team"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "player" next to the right answer in a new sentence and ask again.', 'A collective noun names the whole group as one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER.M7_TK_HERO', 'ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER', 'Calls the trickster a hero or the fooled character the trickster.', '{"question":"In many stories Hare fools Lion. Who is the trickster.","wrong_answer":"Lion","correct_answer":"Hare"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Lion" next to the right answer in a new sentence and ask again.', 'The trickster is the one who plays the trick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER.M7_TK_TRICK_FORCE', 'ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER', 'Thinks a trickster wins by being strong.', '{"question":"How does a trickster usually win.","wrong_answer":"by being the strongest","correct_answer":"by being clever and using a trick"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "by being the strongest" next to the right answer in a new sentence and ask again.', 'Tricksters use their wits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER.M7_TK_LESSON', 'ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER', 'Takes the wrong lesson from a trickster story (it is good to cheat).', '{"question":"A greedy character is tricked and loses his food. What does the story teach.","wrong_answer":"Cheating is always good.","correct_answer":"Greed can lead to trouble."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Cheating is always good." next to the right answer in a new sentence and ask again.', 'The lesson is usually about the fooled character''s fault.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER.M7_TK_TRAIT', 'ENGL.G7.READIN.T1_INTENSIVE_READING_TR.TRICKSTER', 'Describes a trickster as honest and slow.', '{"question":"Which words describe a trickster.","wrong_answer":"honest and slow","correct_answer":"clever and cunning"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "honest and slow" next to the right answer in a new sentence and ask again.', 'A trickster is quick-witted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING.M7_HW_UNEVEN', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING', 'Thinks letters of different sizes, or letters that float above the line, are fine.', '{"question":"Which is a feature of neat handwriting.","wrong_answer":"letters of different sizes","correct_answer":"letters of an even size on the line"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "letters of different sizes" next to the right answer in a new sentence and ask again.', 'Look at the size and the line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING.M7_HW_CROWDED', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING', 'Leaves no clear spaces between words.', '{"question":"What should there be between words in neat handwriting.","wrong_answer":"no space","correct_answer":"a clear space"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "no space" next to the right answer in a new sentence and ask again.', 'A reader needs to see where one word ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING.M7_HW_FAST', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING', 'Thinks writing quickly or pressing hard is the way to neat writing.', '{"question":"What should Peter work on to make his handwriting easier to read.","wrong_answer":"write faster","correct_answer":"keep the letters even and leave spaces between words"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "write faster" next to the right answer in a new sentence and ask again.', 'Neat writing is steady, not rushed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING.M7_HW_DECORATE', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.HANDWRITING', 'Thinks loops, decoration or colour make handwriting better.', '{"question":"Which handwriting is easiest to read.","wrong_answer":"letters with loops and decorations","correct_answer":"plain, even letters on the line"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "letters with loops and decorations" next to the right answer in a new sentence and ask again.', 'Plain letters are easiest to read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING.M7_X_LW_SLANT', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING', 'Lets letters slant in different directions.', '{"question":"Copy a paragraph neatly.","wrong_answer":"letters lean every way","correct_answer":"all letters lean the same way"}'::jsonb, 'The paper moves or the grip changes.', 'Offer "letters lean every way" beside "all letters lean the same way" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the paper still; lean letters one way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING.M7_X_LW_SQUEEZE_END', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING', 'Squeezes words at the end of a line.', '{"question":"A word will not fit at the end of the line. What do you do?","wrong_answer":"squeeze it in small","correct_answer":"start it on the next line"}'::jsonb, 'Unwillingness to start a new line.', 'Offer "squeeze it in small" beside "start it on the next line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Move the word to the next line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING.M7_X_LW_CROSSINGS', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING', 'Leaves crossings-out in the fair copy.', '{"question":"Is a fair copy with three crossings-out neat?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Fair copy and draft are not told apart.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Correct in the draft; the fair copy is clean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING.M7_X_LW_NO_MARGIN', 'ENGL.G7.WRITIN.T1_HANDWRITING_LEGIBILI.LEGIBLE_WRITING', 'Writes into the margin.', '{"question":"Where should writing start?","wrong_answer":"at the edge of the page","correct_answer":"after the margin line"}'::jsonb, 'The margin is ignored.', 'Offer "at the edge of the page" beside "after the margin line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep inside the margin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES.M7_OT_MONOTONE', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES', 'Thinks a good storyteller keeps the same voice throughout.', '{"question":"Which helps a storyteller most when the lion roars.","wrong_answer":"a flat, even voice","correct_answer":"a loud, deep voice"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a flat, even voice" next to the right answer in a new sentence and ask again.', 'The voice should fit the character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES.M7_OT_NO_PAUSE', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES', 'Races through the exciting part with no pause.', '{"question":"What should a storyteller do just before the surprise.","wrong_answer":"speak faster","correct_answer":"pause for a moment"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "speak faster" next to the right answer in a new sentence and ask again.', 'A pause builds suspense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES.M7_OT_NO_EYE', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES', 'Looks at the floor or the ceiling while telling a story.', '{"question":"Where should a storyteller look.","wrong_answer":"at the floor","correct_answer":"at the listeners"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "at the floor" next to the right answer in a new sentence and ask again.', 'Eye contact keeps the audience with you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES.M7_OT_NO_PARTICIPATION', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES', 'Does not let the audience join in a song or a repeated line.', '{"question":"Which technique brings the audience into the story.","wrong_answer":"reading from a paper","correct_answer":"asking them to repeat the chorus"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "reading from a paper" next to the right answer in a new sentence and ask again.', 'A call and answer makes the audience part of the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES.M7_OT_GESTURE', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.ORAL_TECHNIQUES', 'Thinks gestures and facial expression are not needed.', '{"question":"How can a storyteller show that a character is afraid.","wrong_answer":"stand still with no expression","correct_answer":"step back and make a scared face"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "stand still with no expression" next to the right answer in a new sentence and ask again.', 'A face and body show feelings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL.M7_X_PO_READS', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL', 'Reads the narrative or poem from the page instead of performing it.', '{"question":"Perform the oral narrative to the class.","wrong_answer":"reads from the book with head down","correct_answer":"tells it to the audience with eye contact and gestures"}'::jsonb, 'Performance is treated as reading aloud.', 'Offer "reads from the book with head down" beside "tells it to the audience with eye contact and gestures" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Learn the story; look at your audience and tell it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL.M7_X_PO_ONE_VOICE', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL', 'Uses one voice for every character.', '{"question":"Perform the hare and the elephant talking.","wrong_answer":"same voice for both","correct_answer":"a quick, sly voice for the hare, a slow, deep one for the elephant"}'::jsonb, 'Voice changes are not seen as part of the story.', 'Offer "same voice for both" beside "a quick, sly voice for the hare, a slow, deep one for the elephant" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Change your voice for each character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL.M7_X_PO_NO_AUDIENCE', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL', 'Leaves out audience participation where it belongs.', '{"question":"The narrative has a song. What do you do?","wrong_answer":"sing it alone and go on","correct_answer":"teach the chorus and let the audience join"}'::jsonb, 'The child performs at the audience, not with it.', 'Offer "sing it alone and go on" beside "teach the chorus and let the audience join" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Invite the audience into songs and responses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL.M7_X_PO_WRONG_MOOD', 'ENGL.G7.LISTEN.T2_ORAL_PRESENTATIONS_O.PERFORM_ORAL', 'Performs a lullaby loudly and fast, or a praise song flatly.', '{"question":"How should a lullaby be sung?","wrong_answer":"loud and fast","correct_answer":"soft, slow and gentle"}'::jsonb, 'One performance style is used for every form.', 'Offer "loud and fast" beside "soft, slow and gentle" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the style to the form: a lullaby soothes, a praise song celebrates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT.M7_CN_MUCH_MANY', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT', 'Uses much with a count noun or many with a non-count noun.', '{"question":"There were too ___ people at the gate.","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "much" next to the right answer in a new sentence and ask again.', 'People can be counted, so many. Water cannot, so much.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT.M7_CN_PLURAL_NONCOUNT', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT', 'Adds -s to a non-count noun (advices, informations, furnitures, equipments, luggages).', '{"question":"She gave me some good ___.","wrong_answer":"advices","correct_answer":"advice"}'::jsonb, 'Many of these words have a plural form in Kiswahili or in the mother tongue.', 'Offer "advices" next to the right answer in a new sentence and ask again.', 'Advice is one thing that is not counted: some advice, a piece of advice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT.M7_CN_FEW_LITTLE', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT', 'Uses a few with a non-count noun or a little with a count noun.', '{"question":"Add a ___ sugar to the tea.","wrong_answer":"few","correct_answer":"little"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "few" next to the right answer in a new sentence and ask again.', 'Sugar cannot be counted, so a little. Mangoes can, so a few.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT.M7_CN_A_NONCOUNT', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT', 'Puts a or an before a non-count noun (a rice, an advice).', '{"question":"Mama bought ___ rice at the market.","wrong_answer":"a rice","correct_answer":"some rice"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a rice" next to the right answer in a new sentence and ask again.', 'Rice is not counted one by one, so use some, not a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS.M7_PL_ADD_S_IRREGULAR', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'Adds -s to an irregular noun (childs, mans, tooths, foots, mouses).', '{"question":"The ___ are playing football.","wrong_answer":"childs","correct_answer":"children"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "childs" next to the right answer in a new sentence and ask again.', 'Some nouns change inside or have their own plural: child, children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS.M7_PL_Y_IES', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'Adds -s after a consonant and y (babys, storys, countrys).', '{"question":"The nurse looked after three ___.","wrong_answer":"babys","correct_answer":"babies"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "babys" next to the right answer in a new sentence and ask again.', 'After a consonant, y changes to ies: baby, babies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS.M7_PL_F_VES', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'Adds -s to nouns that change f or fe to ves (knifes, leafs, wolfs, lifes).', '{"question":"We cut the meat with two sharp ___.","wrong_answer":"knifes","correct_answer":"knives"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "knifes" next to the right answer in a new sentence and ask again.', 'Say the plural aloud: knives has a v sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS.M7_PL_SAME_FORM', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'Adds -s to a noun that stays the same in the plural (sheeps, fishs, deers).', '{"question":"Our uncle keeps twenty ___ in the village.","wrong_answer":"sheeps","correct_answer":"sheep"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "sheeps" next to the right answer in a new sentence and ask again.', 'Sheep, deer and fish do not change in the plural.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS.M7_PL_ES', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'Adds only -s after s, x, ch, sh (boxs, buss, churchs, dishs).', '{"question":"Mother washed all the ___.","wrong_answer":"dishs","correct_answer":"dishes"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "dishs" next to the right answer in a new sentence and ask again.', 'After sh, ch, s and x add -es so that the ending can be said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT.M7_CN_COUNT_KIND', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.COUNT_NONCOUNT', 'Calls a noun that cannot be counted a count noun, or one that can be counted a non-count noun.', '{"question":"Which noun is a non-count noun.","wrong_answer":"chair","correct_answer":"water"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "chair" next to the right answer in a new sentence and ask again.', 'Ask: can I say one, two, three of it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS.M7_PL_SINGULAR_KIND', 'ENGL.G7.GRAMMA.T2_WORD_CLASSES_NOUNS.PLURALS', 'Cannot tell the singular from the plural of an irregular noun (thinks children is singular, or that mouse is plural).', '{"question":"Which word is a plural noun.","wrong_answer":"child","correct_answer":"children"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "child" next to the right answer in a new sentence and ask again.', 'Plural means more than one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS.M7_BP_BLURB', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS', 'Thinks the blurb is the story or the contents page.', '{"question":"Which part of a book gives a short summary on the back cover.","wrong_answer":"the contents page","correct_answer":"the blurb"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the contents page" next to the right answer in a new sentence and ask again.', 'The blurb is the short note on the back cover.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS.M7_BP_CONTENTS_INDEX', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS', 'Mixes up the contents page and the index.', '{"question":"Where do you find the list of chapters and their page numbers.","wrong_answer":"the index","correct_answer":"the contents page"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the index" next to the right answer in a new sentence and ask again.', 'Contents is at the front, the index is at the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS.M7_BP_TITLE_PAGE', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS', 'Thinks the title page tells the story.', '{"question":"Which part tells the author''s name and the publisher.","wrong_answer":"the glossary","correct_answer":"the title page"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the glossary" next to the right answer in a new sentence and ask again.', 'The title page shows who wrote and published the book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS.M7_BP_GLOSSARY', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.BOOK_PARTS', 'Thinks the glossary is a list of the chapters.', '{"question":"Where would you find the meaning of a hard word used in the book.","wrong_answer":"the contents page","correct_answer":"the glossary"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the contents page" next to the right answer in a new sentence and ask again.', 'A glossary explains hard words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING.M7_X_AS_PUBLISHER', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING', 'Names the publisher as the author.', '{"question":"Who wrote the class reader?","wrong_answer":"the publisher''s name on the spine","correct_answer":"the author named on the cover"}'::jsonb, 'Both names appear on the book.', 'Offer "the publisher''s name on the spine" beside "the author named on the cover" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The author is named with "by" on the title page.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING.M7_X_AS_PLACE_ONLY', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING', 'Gives the place but not the time of the setting.', '{"question":"Describe the setting.","wrong_answer":"a village","correct_answer":"a village near Kisumu during the 1960s"}'::jsonb, 'Setting is thought to be only a place.', 'Offer "a village" beside "a village near Kisumu during the 1960s" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Setting is place and time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING.M7_X_AS_NO_CLUES', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING', 'Guesses the setting without clues from the text.', '{"question":"How do you know it is set long ago?","wrong_answer":"It just is.","correct_answer":"People travel by ox-cart and there are no phones."}'::jsonb, 'Clues are not looked for.', 'Offer "It just is." beside "People travel by ox-cart and there are no phones." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find clues: transport, clothes, tools.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING.M7_X_AS_CHARACTER_AUTHOR', 'ENGL.G7.READIN.T2_INTENSIVE_READING_CL.AUTHOR_SETTING', 'Thinks the narrator is the author.', '{"question":"The story says \"I\". Is the narrator the author?","wrong_answer":"Yes","correct_answer":"Not always; the narrator can be a character"}'::jsonb, 'First person is read as the writer.', 'Offer "Yes" beside "Not always; the narrator can be a character" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The narrator may be a character the author made up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS.M7_EM_QMARK_STATEMENT', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS', 'Ends a statement or a reported question with a question mark (He asked where I was going?).', '{"question":"Which sentence is correct.","wrong_answer":"She asked me where I was going?","correct_answer":"She asked me where I was going."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She asked me where I was going?" next to the right answer in a new sentence and ask again.', 'A question mark is for the exact question, not for a sentence that tells about it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS.M7_EM_FULLSTOP_QUESTION', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS', 'Ends a real question with a full stop (Where is the market.).', '{"question":"Which sentence is correct.","wrong_answer":"Where is the market.","correct_answer":"Where is the market?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Where is the market." next to the right answer in a new sentence and ask again.', 'A sentence that asks something ends with a question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS.M7_EM_NO_EXCLAMATION', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS', 'Uses a full stop where a strong feeling or a command needs an exclamation mark (Watch out.)', '{"question":"Which sentence is correct.","wrong_answer":"Watch out.","correct_answer":"Watch out!"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Watch out." next to the right answer in a new sentence and ask again.', 'A shout or sudden warning takes an exclamation mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS.M7_EM_MANY_MARKS', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS', 'Writes several marks together (Help!!! What???).', '{"question":"Which sentence is correct.","wrong_answer":"Stop thief!!!","correct_answer":"Stop thief!"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Stop thief!!!" next to the right answer in a new sentence and ask again.', 'One mark is enough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS.M7_EM_NO_CAPITAL', 'ENGL.G7.WRITIN.T2_MECHANICS_OF_WRITING.END_MARKS', 'Forgets the capital letter at the start of the next sentence after an end mark.', '{"question":"Which is correct.","wrong_answer":"It was late. we went home.","correct_answer":"It was late. We went home."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "It was late. we went home." next to the right answer in a new sentence and ask again.', 'A new sentence begins with a capital letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING.M7_IO_MIXED', 'ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING', 'Thinks reading a timetable is reading for meaning.', '{"question":"You read a bus timetable to find when the next bus leaves. Which kind of reading is this.","wrong_answer":"reading for meaning","correct_answer":"reading for information"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "reading for meaning" next to the right answer in a new sentence and ask again.', 'You are looking for a fact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING.M7_IO_STORY_INFO', 'ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING', 'Thinks a story is read only for information.', '{"question":"Which text is mainly read for meaning and enjoyment.","wrong_answer":"a notice board","correct_answer":"a short story"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a notice board" next to the right answer in a new sentence and ask again.', 'A story is read to enjoy and understand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING.M7_IO_SKIM', 'ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING', 'Reads the whole text slowly when only one fact is needed.', '{"question":"You need the date on a poster. What is the quickest way.","wrong_answer":"read every word slowly","correct_answer":"look quickly for the date"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "read every word slowly" next to the right answer in a new sentence and ask again.', 'Look for the one fact you need.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING.M7_X_IO_SPEED', 'ENGL.G7.READIN.T3_READING_INFORMATION_.INFO_OR_MEANING', 'Reads a story at scanning speed and misses its meaning.', '{"question":"You are reading a short story for its message. How do you read?","wrong_answer":"run the eyes down for key words","correct_answer":"read every line and think about it"}'::jsonb, 'One reading speed is used for every purpose.', 'Offer "run the eyes down for key words" beside "read every line and think about it" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read for meaning slowly; scan only for a fact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS.M7_IV_ED_ON_IRREGULAR', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS', 'Adds -ed to an irregular verb (goed, eated, buyed, thinked).', '{"question":"Yesterday we ___ to the lake.","wrong_answer":"goed","correct_answer":"went"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "goed" next to the right answer in a new sentence and ask again.', 'Go is an irregular verb. Its past is went.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS.M7_IV_PARTICIPLE_PAST', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS', 'Uses the past form where the past participle is needed (has went, have saw, had ate).', '{"question":"The bell has already ___.","wrong_answer":"rang","correct_answer":"rung"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "rang" next to the right answer in a new sentence and ask again.', 'After has, have or had, use the past participle: has rung.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS.M7_IV_PAST_PARTICIPLE', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS', 'Uses the participle for the plain past (I seen it, she done it, we gone home).', '{"question":"I ___ the lion yesterday.","wrong_answer":"seen","correct_answer":"saw"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "seen" next to the right answer in a new sentence and ask again.', 'Without has, have or had, use the past form: I saw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS.M7_IV_REGULAR_IRREGULAR', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.IRREGULAR_VERBS', 'Makes a regular verb irregular or an irregular verb regular (runned, swimmed, but wented).', '{"question":"Our teacher ___ us a story last week.","wrong_answer":"telled","correct_answer":"told"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "telled" next to the right answer in a new sentence and ask again.', 'Tell is irregular: told.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE.M7_TC_PRESENT_FOR_PAST', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE', 'Uses the present with a past time word (Yesterday I go to the market).', '{"question":"Yesterday, Atieno ___ to the market.","wrong_answer":"goes","correct_answer":"went"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "goes" next to the right answer in a new sentence and ask again.', 'Yesterday is past time, so the verb is in the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE.M7_TC_PAST_FOR_FUTURE', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE', 'Uses the past with a future time word (Tomorrow we went to Mombasa).', '{"question":"Tomorrow we ___ to Mombasa.","wrong_answer":"went","correct_answer":"will go"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "went" next to the right answer in a new sentence and ask again.', 'Tomorrow has not happened, so the verb is in the future.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE.M7_TC_WILL_PAST', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE', 'Uses will with a past form (will went, will came).', '{"question":"Next week our class ___ a trip.","wrong_answer":"will took","correct_answer":"will take"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "will took" next to the right answer in a new sentence and ask again.', 'After will, the plain verb is used: will take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE.M7_TC_HABIT_PRESENT_CONT', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE', 'Uses the continuous for a habit (She is going to church every Sunday).', '{"question":"Every Sunday, Mama ___ to church.","wrong_answer":"is going","correct_answer":"goes"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "is going" next to the right answer in a new sentence and ask again.', 'A habit that happens again and again uses the simple present.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE.M7_TC_WRONG_TIME', 'ENGL.G7.GRAMMA.T3_VERBS_AND_TENSE.TENSE_CHOICE', 'Chooses a tense that does not fit the time word (a continuous or participle form where a simple tense is needed).', '{"question":"Last Saturday we ___ the maize.","wrong_answer":"harvesting","correct_answer":"harvested"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "harvesting" next to the right answer in a new sentence and ask again.', 'Match the verb to the time word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE.M7_PST_LINE_STANZA', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'Calls a line a stanza or a stanza a line.', '{"question":"What is a group of lines in a poem called.","wrong_answer":"a line","correct_answer":"a stanza"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a line" next to the right answer in a new sentence and ask again.', 'A stanza is a group of lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE.M7_PST_RHYME_SPELLING', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'Chooses rhyming words by spelling instead of sound (cough and through).', '{"question":"Which pair rhymes.","wrong_answer":"cough and through","correct_answer":"light and night"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "cough and through" next to the right answer in a new sentence and ask again.', 'Say the words aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE.M7_PST_REFRAIN', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'Does not see the refrain (the repeated line or words).', '{"question":"What is a refrain.","wrong_answer":"the last line","correct_answer":"a line that comes back again and again"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the last line" next to the right answer in a new sentence and ask again.', 'A refrain is repeated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE.M7_PST_PROSE', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'Calls a poem a story because it tells something, or a story a poem.', '{"question":"Which is a poem.","wrong_answer":"Our class went to the farm. We saw cows.","correct_answer":"Sun on the hills, sun on the river, / light in the morning, light for ever."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Our class went to the farm. We saw cows." next to the right answer in a new sentence and ask again.', 'A poem is set in lines with rhythm and often rhyme.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE.M7_PST_COUNT', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'Counts the number of stanzas or lines wrongly.', '{"question":"How many stanzas does the poem have.","wrong_answer":"the number of lines","correct_answer":"the number of groups of lines"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the number of lines" next to the right answer in a new sentence and ask again.', 'Count the groups separated by a gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH.M7_NP_OPENING_EVENT', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH', 'Chooses an event from the middle for the opening of a narrative paragraph.', '{"question":"Which sentence best opens a narrative paragraph about a school trip.","wrong_answer":"Suddenly the bus broke down.","correct_answer":"On Friday morning our class set off for Nakuru."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Suddenly the bus broke down." next to the right answer in a new sentence and ask again.', 'The opening sets the scene: who, where, when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH.M7_NP_ORDER', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH', 'Puts the events out of order.', '{"question":"Which sentence comes last in the paragraph.","wrong_answer":"First we ate lunch.","correct_answer":"At last we reached home."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "First we ate lunch." next to the right answer in a new sentence and ask again.', 'Look for the closing: finally, at last, in the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH.M7_NP_OFF_TOPIC', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH', 'Keeps a sentence that is about something else in the paragraph.', '{"question":"Which sentence does not belong in the paragraph.","wrong_answer":"My uncle sells shoes in Eldoret.","correct_answer":"We paid the fare and sat down."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "My uncle sells shoes in Eldoret." next to the right answer in a new sentence and ask again.', 'Every sentence must belong to the same story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH.M7_NP_NO_CLOSING', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.NARRATIVE_PARAGRAPH', 'Ends the paragraph in the middle of the action with no closing.', '{"question":"Which sentence best closes the paragraph.","wrong_answer":"Then the driver turned left.","correct_answer":"We were tired but happy when we got home."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Then the driver turned left." next to the right answer in a new sentence and ask again.', 'A closing tells how the events ended or how the people felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING.M7_X_PW_NO_TOPIC', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING', 'Writes a paragraph with no topic sentence.', '{"question":"Which opening tells the reader what the paragraph is about?","wrong_answer":"He carried water.","correct_answer":"Our class prefect is a true leader."}'::jsonb, 'The child starts with a detail.', 'Offer "He carried water." beside "Our class prefect is a true leader." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Begin with the main idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING.M7_X_PW_EXAMPLE_OFF', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING', 'Adds an example that does not support the point.', '{"question":"Point: our prefect is fair. Which example fits?","wrong_answer":"He has a new bag.","correct_answer":"He gives everyone a turn to speak."}'::jsonb, 'Any example is added.', 'Offer "He has a new bag." beside "He gives everyone a turn to speak." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the example proves the point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING.M7_X_PW_NO_CLOSE', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING', 'Stops without a closing sentence.', '{"question":"How should the paragraph end?","wrong_answer":"with another detail","correct_answer":"with a sentence that sums up"}'::jsonb, 'The child stops when ideas run out.', 'Offer "with another detail" beside "with a sentence that sums up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End with a sentence that sums up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING.M7_X_PW_MANY_IDEAS', 'ENGL.G7.WRITIN.T3_WRITING_NARRATIVE_PA.PARAGRAPH_WRITING', 'Puts several main ideas in one paragraph.', '{"question":"A paragraph covers hygiene, sports and exams. Right?","wrong_answer":"Yes","correct_answer":"No: one main idea per paragraph"}'::jsonb, 'Paragraphs are seen as blocks of text.', 'Offer "Yes" beside "No: one main idea per paragraph" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One main idea per paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL.M7_SG_GENERAL_SPECIFIC', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL', 'Takes a detail for the general idea.', '{"question":"Which is a question about the general idea of a text on Lake Victoria.","wrong_answer":"How deep is the lake at its deepest point?","correct_answer":"What is the text mostly about?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "How deep is the lake at its deepest point?" next to the right answer in a new sentence and ask again.', 'A general question asks about the whole text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL.M7_SG_SPECIFIC_GENERAL', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL', 'Takes the general idea for a specific detail.', '{"question":"Which question asks for a specific detail.","wrong_answer":"What is the text about?","correct_answer":"On what date did the festival begin?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "What is the text about?" next to the right answer in a new sentence and ask again.', 'A specific question has a short, exact answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL.M7_SG_NEAR_DETAIL', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL', 'Picks a detail that is near the answer but is not what was asked.', '{"question":"The text says the match started at two and ended at four. At what time did the match end.","wrong_answer":"two o''clock","correct_answer":"four o''clock"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "two o''clock" next to the right answer in a new sentence and ask again.', 'Match the question word: ended asks for the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL.M7_SG_NUMBER_SLIP', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.SPECIFIC_GENERAL', 'Gives a number from the wrong place in the text.', '{"question":"The text says 40 learners went on the trip and 5 teachers. How many teachers went.","wrong_answer":"40","correct_answer":"5"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "40" next to the right answer in a new sentence and ask again.', 'Find the number that goes with the noun asked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M7_X_LR_DETAIL_AS_ISSUE', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Gives a detail as the key issue.', '{"question":"A song on land travel mentions a red matatu and warns about overloading. Key issue?","wrong_answer":"a red matatu","correct_answer":"overloading is dangerous"}'::jsonb, 'Vivid details stick.', 'Offer "a red matatu" beside "overloading is dangerous" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what is the song worried or happy about?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M7_X_LR_OFF_RESPONSE', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Responds with something unrelated to the talk.', '{"question":"Respond to the talk on good leaders.","wrong_answer":"I like football.","correct_answer":"A good leader listens, like our class prefect."}'::jsonb, 'The child says what is on his or her mind.', 'Offer "I like football." beside "A good leader listens, like our class prefect." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link your response to what was said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M7_X_LR_MISHEARD', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Responds to a word misheard and misses the point.', '{"question":"The speaker says \"leaders serve\". Response?","wrong_answer":"Leaders swerve on the road.","correct_answer":"A leader serves the people, not himself."}'::jsonb, 'Attention drifts and a sound-alike is caught.', 'Offer "Leaders swerve on the road." beside "A leader serves the people, not himself." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the point before you respond.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M7_X_LR_REPEATS', 'ENGL.G7.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Repeats the speaker''s words without responding.', '{"question":"What is your view on the song''s message?","wrong_answer":"Overloading is dangerous. (repeated)","correct_answer":"I agree; I will refuse to board an overloaded matatu."}'::jsonb, 'Repeating feels safe.', 'Offer "Overloading is dangerous. (repeated)" beside "I agree; I will refuse to board an overloaded matatu." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add your own view or action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M7_RS_SKIM_SCAN', 'ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Mixes up skimming and scanning.', '{"question":"You want to find one name quickly in a long text. Which strategy is best.","wrong_answer":"skimming","correct_answer":"scanning"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "skimming" next to the right answer in a new sentence and ask again.', 'Scanning looks for one fact. Skimming gets the general idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M7_RS_WRONG', 'ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Chooses something that is not a strategy (guessing, skipping, reading aloud every word) for the purpose.', '{"question":"You do not understand a sentence. Which strategy helps.","wrong_answer":"skipping it","correct_answer":"reading it again with the words around it"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "skipping it" next to the right answer in a new sentence and ask again.', 'A reading strategy helps you to understand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M7_X_RS_REREAD_NEVER', 'ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Never rereads a confusing sentence.', '{"question":"A sentence does not make sense. What do you do?","wrong_answer":"go on to the next page","correct_answer":"reread it slowly"}'::jsonb, 'Rereading feels like failure.', 'Offer "go on to the next page" beside "reread it slowly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Reread a hard sentence before going on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M7_X_RS_PREVIEW_SKIP', 'ENGL.G7.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Starts reading without previewing title, headings and pictures.', '{"question":"Before reading an article on hygiene, you should ...","wrong_answer":"start at the first word","correct_answer":"look at the title, headings and pictures"}'::jsonb, 'Previewing is not known as a strategy.', 'Offer "start at the first word" beside "look at the title, headings and pictures" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Preview first: it tells you what to expect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT.M7_SP_NO_S', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'Leaves out -s after he, she, it or a single name (She walk to school).', '{"question":"Wanjiru ___ to school every day.","wrong_answer":"walk","correct_answer":"walks"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "walk" next to the right answer in a new sentence and ask again.', 'One person (she, he, it) takes -s or -es on the verb in the simple present.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT.M7_SP_S_PLURAL', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'Adds -s after I, you, we or they (They plays, we likes).', '{"question":"The boys ___ football after lessons.","wrong_answer":"plays","correct_answer":"play"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "plays" next to the right answer in a new sentence and ask again.', 'With a plural subject the verb has no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT.M7_SP_DOES_S', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'Adds -s to the verb after does (She does not walks).', '{"question":"My brother does not ___ coffee.","wrong_answer":"drinks","correct_answer":"drink"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "drinks" next to the right answer in a new sentence and ask again.', 'After do or does the plain verb is used: does not drink.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT.M7_SP_DO_THIRD', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'Uses do not after he, she or it (She do not know).', '{"question":"Our neighbour ___ not own a car.","wrong_answer":"do","correct_answer":"does"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "do" next to the right answer in a new sentence and ask again.', 'One person takes does, not do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT.M7_SP_ES', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'Adds only -s after ch, sh, s, x, o, or y after a consonant (she washs, he trys).', '{"question":"The cook ___ the dishes after supper.","wrong_answer":"washs","correct_answer":"washes"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "washs" next to the right answer in a new sentence and ask again.', 'After sh, ch, s, x and o, add -es. After a consonant and y, y becomes ies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST.M7_SPA_DID_PAST', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST', 'Puts the past form after did (Did you went? She did not came).', '{"question":"Did you ___ the match yesterday?","wrong_answer":"watched","correct_answer":"watch"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "watched" next to the right answer in a new sentence and ask again.', 'Did already shows the past, so the verb is plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST.M7_SPA_NO_ED', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST', 'Leaves the verb plain in a past story (Yesterday she walk home).', '{"question":"Last Saturday we ___ the maize.","wrong_answer":"harvest","correct_answer":"harvested"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "harvest" next to the right answer in a new sentence and ask again.', 'Last Saturday is past. A regular verb adds -ed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST.M7_SPA_SPELL_ED', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST', 'Spells -ed wrongly (stoped, studyed, plaied).', '{"question":"The driver ___ at the junction.","wrong_answer":"stoped","correct_answer":"stopped"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "stoped" next to the right answer in a new sentence and ask again.', 'A short verb with one vowel and one consonant doubles the last letter before -ed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST.M7_SPA_WAS_WERE', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PAST', 'Uses was with you, we or they, or were with I, he, she, it (We was late).', '{"question":"The children ___ happy to see the visitors.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "was" next to the right answer in a new sentence and ask again.', 'A plural subject takes were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT.M7_SP_WRONG_FORM', 'ENGL.G7.GRAMMA.T4_VERBS_AND_TENSE.SIMPLE_PRESENT', 'Uses an -ing or a past form where the simple present is needed.', '{"question":"My sister ___ to music while she studies.","wrong_answer":"listening","correct_answer":"listens"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "listening" next to the right answer in a new sentence and ask again.', 'A habit uses the simple present.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES.M7_CR_MINOR_FOR_MAIN', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES', 'Names a minor character as the main character.', '{"question":"Who is the main character of the story.","wrong_answer":"a character who only appears once","correct_answer":"the person the story is about"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a character who only appears once" next to the right answer in a new sentence and ask again.', 'The main character is in most of the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES.M7_CR_MAIN_FOR_MINOR', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES', 'Names the main character when a minor one is asked.', '{"question":"Who is a minor character in the story.","wrong_answer":"the girl the story is about","correct_answer":"the shopkeeper who sells her the bread"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the girl the story is about" next to the right answer in a new sentence and ask again.', 'A minor character plays a small part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES.M7_CR_PLACE_CHARACTER', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES', 'Names a place, an object or an event as a character.', '{"question":"Who is a character in the story.","wrong_answer":"the village","correct_answer":"the goat"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the village" next to the right answer in a new sentence and ask again.', 'A character is a person or an animal that acts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES.M7_CR_ROLE', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_ROLES', 'Says the wrong thing about what a character does in the story.', '{"question":"What does the character do to move the story on.","wrong_answer":"something done by another character","correct_answer":"the thing the character does in the passage"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "something done by another character" next to the right answer in a new sentence and ask again.', 'Find the line where the character acts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS.M7_CT_OPPOSITE', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS', 'Chooses the opposite trait to the one the actions show.', '{"question":"Which word best describes the character.","wrong_answer":"the opposite of the right word","correct_answer":"the word the actions show"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the opposite of the right word" next to the right answer in a new sentence and ask again.', 'Look at what the person does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS.M7_CT_NAME_ONLY', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS', 'Judges a character by the name or one word.', '{"question":"Which word describes the character.","wrong_answer":"a trait chosen from the name","correct_answer":"a trait supported by actions"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a trait chosen from the name" next to the right answer in a new sentence and ask again.', 'Do not judge from the name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS.M7_CT_WRONG_EVIDENCE', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS', 'Chooses a line that does not show the trait as evidence.', '{"question":"Which line shows the trait.","wrong_answer":"a line about the setting","correct_answer":"a line about what the character does"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a line about the setting" next to the right answer in a new sentence and ask again.', 'Evidence is something the character says or does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT.M7_PD_NO_CLUE', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT', 'Predicts something with no clue in the passage.', '{"question":"What will probably happen next.","wrong_answer":"an event with no clue","correct_answer":"an event the clues point to"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an event with no clue" next to the right answer in a new sentence and ask again.', 'A prediction needs a clue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT.M7_PD_CONTRADICTS', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT', 'Predicts something that goes against the passage.', '{"question":"What will probably happen next.","wrong_answer":"an event against the story","correct_answer":"an event that fits the story"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an event against the story" next to the right answer in a new sentence and ask again.', 'The prediction must agree with what has been told.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT.M7_PD_ALREADY_HAPPENED', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT', 'Chooses an event that has already happened.', '{"question":"What will probably happen next.","wrong_answer":"an event already told","correct_answer":"an event not yet told"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an event already told" next to the right answer in a new sentence and ask again.', 'A prediction is about what has not happened yet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT.M7_PD_WRONG_CLUE', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.PREDICT', 'Chooses a sentence that is not a clue for the prediction.', '{"question":"Which sentence is the best clue for the prediction.","wrong_answer":"a sentence about something else","correct_answer":"a sentence that points to the prediction"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a sentence about something else" next to the right answer in a new sentence and ask again.', 'Ask: which sentence makes this likely.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS.M7_X_CT_ACTION_AS_TRAIT', 'ENGL.G7.READIN.T4_INTENSIVE_READING_CL.CHARACTER_TRAITS', 'Gives an action as a trait.', '{"question":"The monster ate the villagers'' cattle. Its trait?","wrong_answer":"eating cattle","correct_answer":"greedy"}'::jsonb, 'Action and trait are not told apart.', 'Offer "eating cattle" beside "greedy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A trait is a describing word for what the character is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES.M7_PE_EXAMPLE_OFF', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES', 'Chooses an example that is about something else.', '{"question":"Topic: Our school keeps the compound clean. Which sentence gives a good example.","wrong_answer":"Our school has a big football field.","correct_answer":"Every Friday each class sweeps its own corner."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Our school has a big football field." next to the right answer in a new sentence and ask again.', 'An example must show the topic sentence is true.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES.M7_PE_REPEAT', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES', 'Repeats the topic sentence in other words instead of giving an example.', '{"question":"Which sentence is an example.","wrong_answer":"Our school is very clean.","correct_answer":"Last term our school won the cleanest compound prize."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Our school is very clean." next to the right answer in a new sentence and ask again.', 'An example gives a real case, not the same idea again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES.M7_PE_CONNECTOR', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES', 'Chooses the wrong words to bring in an example (However, as a result, finally).', '{"question":"Which words bring in an example.","wrong_answer":"However","correct_answer":"For example"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "However" next to the right answer in a new sentence and ask again.', 'For example and for instance bring in an example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES.M7_PE_INCIDENT_GENERAL', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES', 'Thinks a general statement is an incident.', '{"question":"Which sentence tells an incident.","wrong_answer":"Children like to play.","correct_answer":"Yesterday a boy found a purse and took it to the teacher."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Children like to play." next to the right answer in a new sentence and ask again.', 'An incident is one thing that happened at one time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES.M7_PE_KEEPS_OFF_TOPIC', 'ENGL.G7.WRITIN.T4_PARAGRAPHING_USING_E.PARAGRAPH_EXAMPLES', 'Keeps a sentence about something else in the paragraph, or takes a sentence that belongs for the odd one.', '{"question":"Which sentence does not belong in the paragraph.","wrong_answer":"a sentence that belongs","correct_answer":"the sentence about something else"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a sentence that belongs" next to the right answer in a new sentence and ask again.', 'Every sentence must be about the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS.M7_X_PS_T_D', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS', 'Swaps /t/ and /d/ at the end of words.', '{"question":"Say: bed","wrong_answer":"bet","correct_answer":"bed"}'::jsonb, 'Final voiced sounds are devoiced.', 'Offer "bet" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the voice on: bed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS.M7_X_PS_L_R', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS', 'Swaps /l/ and /r/.', '{"question":"Say: The leader read the rules.","wrong_answer":"The reader lead the lules.","correct_answer":"The leader read the rules."}'::jsonb, 'L and r are one sound in some home languages.', 'Offer "The reader lead the lules." beside "The leader read the rules." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up for l; curled for r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS.M7_X_PS_PULL_POOL', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS', 'Says /ʊ/ (pull) and /uː/ (pool) the same.', '{"question":"Say: pull, pool","wrong_answer":"both the same","correct_answer":"pull short, pool long"}'::jsonb, 'One u sound in the home language.', 'Offer "both the same" beside "pull short, pool long" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pull is short and relaxed; pool is long with round lips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS.M7_X_PS_NG_NG_G', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.PRONOUNCE_SOUNDS', 'Says /ŋ/ as n plus g, or as n.', '{"question":"Say: singing","wrong_answer":"sin-ging (hard g) or sinin","correct_answer":"si-ŋiŋ"}'::jsonb, 'Spelling ng is read as two sounds.', 'Offer "sin-ging (hard g) or sinin" beside "si-ŋiŋ" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ng is one sound at the back of the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS.M7_X_WS_NOUN_VERB', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS', 'Stresses the noun and the verb the same way.', '{"question":"They will ___ (contract) the builder.","wrong_answer":"CONtract","correct_answer":"conTRACT"}'::jsonb, 'The stress-meaning rule is not applied.', 'Offer "CONtract" beside "conTRACT" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Verbs often move the stress to the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS.M7_X_WS_LAST', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS', 'Stresses the last syllable of long words.', '{"question":"Say: election","wrong_answer":"elec-TION","correct_answer":"e-LEC-tion"}'::jsonb, 'The ending -tion looks strong.', 'Offer "elec-TION" beside "e-LEC-tion" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Before -tion, the syllable is strong: e-LEC-tion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS.M7_X_WS_EQUAL', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS', 'Gives every syllable equal weight.', '{"question":"Say: independence","wrong_answer":"IN-DE-PEN-DENCE","correct_answer":"in-de-PEN-dence"}'::jsonb, 'Syllable-timed home languages.', 'Offer "IN-DE-PEN-DENCE" beside "in-de-PEN-dence" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One strong beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS.M7_X_WS_MEANING', 'ENGL.G7.LISTEN.T5_PRONUNCIATION_SOUNDS.WORD_STRESS', 'Does not hear that stress changes the meaning.', '{"question":"Is \"PROgress\" the same word class as \"proGRESS\"?","wrong_answer":"Yes","correct_answer":"No: noun and verb"}'::jsonb, 'Stress is seen as accent, not meaning.', 'Offer "Yes" beside "No: noun and verb" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen: the stress tells you noun or verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES.M7_AD_MORE_ER', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'Uses more with -er (more taller) or most with -est (most tallest).', '{"question":"Kamau is ___ than his brother.","wrong_answer":"more taller","correct_answer":"taller"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "more taller" next to the right answer in a new sentence and ask again.', 'A short adjective takes -er, with no more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES.M7_AD_LONG_ER', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'Adds -er or -est to a long adjective (beautifuler, expensivest).', '{"question":"This dress is ___ than that one.","wrong_answer":"beautifuler","correct_answer":"more beautiful"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "beautifuler" next to the right answer in a new sentence and ask again.', 'A long adjective takes more and most.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES.M7_AD_IRREGULAR', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'Makes the wrong form of good, bad or far (gooder, badder, the goodest).', '{"question":"Her marks are ___ than mine.","wrong_answer":"gooder","correct_answer":"better"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "gooder" next to the right answer in a new sentence and ask again.', 'Good is irregular: good, better, best.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES.M7_AD_THAN_THE', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'Uses the with the comparative or than with the superlative.', '{"question":"Mount Kenya is the ___ mountain in Kenya.","wrong_answer":"higher","correct_answer":"highest"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "higher" next to the right answer in a new sentence and ask again.', 'The goes with the superlative. Than goes with the comparative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES.M7_AD_SPELL_ER', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'Spells the -er or -est form wrongly (bigger written biger, happier written happyer).', '{"question":"Today is ___ than yesterday. (hot)","wrong_answer":"hoter","correct_answer":"hotter"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hoter" next to the right answer in a new sentence and ask again.', 'A short adjective with one vowel and one consonant doubles the last letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES.M7_AD_PLAIN_FORM', 'ENGL.G7.GRAMMA.T5_COMPARATIVE_AND_SUPE.ADJECTIVE_DEGREES', 'Uses the plain adjective where the comparative or the superlative is needed (Juma is tall than Peter).', '{"question":"Juma is ___ than Peter.","wrong_answer":"tall","correct_answer":"taller"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "tall" next to the right answer in a new sentence and ask again.', 'Than needs a comparative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON.M7_ML_DETAIL', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON', 'Gives a detail of the story as the lesson.', '{"question":"What lesson does the story teach.","wrong_answer":"a detail from the story","correct_answer":"a lesson about how to behave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a detail from the story" next to the right answer in a new sentence and ask again.', 'A lesson applies to real life, not only to the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON.M7_ML_NOT_TAUGHT', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON', 'Gives a lesson that the story does not teach.', '{"question":"What lesson does the story teach.","wrong_answer":"a lesson the story does not teach","correct_answer":"the lesson the story ends with"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a lesson the story does not teach" next to the right answer in a new sentence and ask again.', 'Check the ending: what was the result of the choice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON.M7_ML_OPPOSITE', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON', 'Gives the opposite of the lesson (greed pays).', '{"question":"What lesson does the story teach.","wrong_answer":"the opposite of the lesson","correct_answer":"the lesson the ending shows"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the opposite of the lesson" next to the right answer in a new sentence and ask again.', 'Ask what happened to the character who did wrong.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON.M7_ML_HERO_TRAIT', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.MORAL_LESSON', 'Gives a quality that does not make a hero (richness, size) for the hero of a legend.', '{"question":"What makes the character a hero in the legend.","wrong_answer":"being rich","correct_answer":"being brave and helping the people"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "being rich" next to the right answer in a new sentence and ask again.', 'A hero acts bravely for others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE.M7_X_RL_RETELL', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE', 'Retells the legend instead of relating it.', '{"question":"Relate the hero to real life.","wrong_answer":"He fought the monster and won.","correct_answer":"Like the hero, our nurse risks her life in floods."}'::jsonb, 'Retelling is easier.', 'Offer "He fought the monster and won." beside "Like the hero, our nurse risks her life in floods." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name a real person or situation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE.M7_X_RL_SURFACE', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE', 'Links on a surface detail.', '{"question":"Relate the story of a monster that eats greedy people to life.","wrong_answer":"We also have big animals.","correct_answer":"Greed harms people in our community too, like a man who cheated his neighbours."}'::jsonb, 'Any shared detail seems enough.', 'Offer "We also have big animals." beside "Greed harms people in our community too, like a man who cheated his neighbours." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link the lesson, not the object.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE.M7_X_RL_NO_WHY', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE', 'Cannot say why the story matters to the community.', '{"question":"Why are legends told in your community?","wrong_answer":"For fun.","correct_answer":"They teach courage and remind us of our history."}'::jsonb, 'Purpose is not considered.', 'Offer "For fun." beside "They teach courage and remind us of our history." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what the story teaches people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE.M7_X_RL_CHANGES_TEXT', 'ENGL.G7.READIN.T5_INTENSIVE_READING_OR.RELATE_TO_LIFE', 'Changes the text to fit the real-life story.', '{"question":"What did the hero do in the legend?","wrong_answer":"He ran away, like my cousin did.","correct_answer":"He stood and fought."}'::jsonb, 'Memory overwrites the text.', 'Offer "He ran away, like my cousin did." beside "He stood and fought." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep what the text says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M7_FL_WRONG_CLOSING', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Uses a formal closing in a friendly letter (Yours faithfully to a friend).', '{"question":"Which closing suits a letter to your cousin.","wrong_answer":"Yours faithfully","correct_answer":"Your loving cousin"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Yours faithfully" next to the right answer in a new sentence and ask again.', 'A friendly letter ends warmly: Your friend, Yours lovingly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M7_FL_RECEIVER_ADDRESS', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Writes the receiver''s address at the top of a friendly letter.', '{"question":"Which address goes at the top of a friendly letter.","wrong_answer":"the address of the person you are writing to","correct_answer":"your own address"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the address of the person you are writing to" next to the right answer in a new sentence and ask again.', 'A friendly letter shows where the writer lives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M7_FL_SUBJECT_LINE', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Adds a subject line to a friendly letter.', '{"question":"Which part is NOT needed in a friendly letter.","wrong_answer":"a greeting","correct_answer":"a subject line in capitals"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a greeting" next to the right answer in a new sentence and ask again.', 'A subject line belongs to a formal letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M7_FL_GREETING', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Starts a friendly letter with a formal greeting (Dear Sir).', '{"question":"Which greeting suits a letter to your friend Achieng.","wrong_answer":"Dear Sir","correct_answer":"Dear Achieng,"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Dear Sir" next to the right answer in a new sentence and ask again.', 'Use the name of the person you know.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M7_FL_ORDER', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Puts the parts in the wrong order (the name before the closing).', '{"question":"Which part comes last in a friendly letter.","wrong_answer":"the closing","correct_answer":"the writer''s name"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the closing" next to the right answer in a new sentence and ask again.', 'The name comes after the closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE.M7_X_FL_FORMAL', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE', 'Writes a friendly letter in a formal tone.', '{"question":"Opening for a letter to a cousin?","wrong_answer":"I write to inform you of my progress.","correct_answer":"How are you? I have so much news to share!"}'::jsonb, 'Formal letter habits.', 'Offer "I write to inform you of my progress." beside "How are you? I have so much news to share!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write as you would speak to the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE.M7_X_FL_NO_PARAGRAPHS', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE', 'Writes the body as one block.', '{"question":"Three pieces of news: how many paragraphs?","wrong_answer":"one","correct_answer":"three"}'::jsonb, 'Paragraphing is skipped.', 'Offer "one" beside "three" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'New news, new paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE.M7_X_FL_TWO_ADDRESSES', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE', 'Adds the receiver''s address.', '{"question":"How many addresses?","wrong_answer":"two","correct_answer":"one"}'::jsonb, 'Formal letter layout is mixed in.', 'Offer "two" beside "one" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only your own address.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE.M7_X_FL_NO_CLOSING', 'ENGL.G7.WRITIN.T5_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER_WRITE', 'Ends without a closing line and name.', '{"question":"What comes after the last paragraph?","wrong_answer":"nothing","correct_answer":"Your loving cousin, and the name"}'::jsonb, 'The child stops with the news.', 'Offer "nothing" beside "Your loving cousin, and the name" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Close warmly and sign your name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT.M7_PI_RUDE', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT', 'Interrupts with a command (Stop talking, let me speak).', '{"question":"Which is a polite way to interrupt a speaker.","wrong_answer":"Stop! Let me talk now.","correct_answer":"Excuse me, may I say something?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Stop! Let me talk now." next to the right answer in a new sentence and ask again.', 'Ask permission and use please or excuse me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT.M7_PI_NO_WAIT', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT', 'Interrupts without waiting for a pause in the talk.', '{"question":"When is the best moment to join a conversation.","wrong_answer":"while someone is in the middle of a sentence","correct_answer":"when the speaker pauses"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "while someone is in the middle of a sentence" next to the right answer in a new sentence and ask again.', 'Wait for a pause before you ask for a turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT.M7_PI_NON_VERBAL', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT', 'Thinks a non-verbal cue is something said.', '{"question":"Which is a non-verbal way to ask for a turn.","wrong_answer":"saying Excuse me","correct_answer":"raising a hand slightly"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "saying Excuse me" next to the right answer in a new sentence and ask again.', 'Non-verbal means without words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT.M7_PI_TURN_TAKING', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.POLITE_INTERRUPT', 'Does not give the other person a turn after speaking.', '{"question":"After you have given your point in a group talk, what do you do.","wrong_answer":"keep talking","correct_answer":"invite the next person to speak"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "keep talking" next to the right answer in a new sentence and ask again.', 'Turn taking means everyone speaks in turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING.M7_X_TT_DOMINATES', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING', 'Keeps the floor and does not let others speak.', '{"question":"In a group discussion on drugs, you have spoken three times. What next?","wrong_answer":"speak again","correct_answer":"invite someone who has not spoken"}'::jsonb, 'The child equates talking most with doing well.', 'Offer "speak again" beside "invite someone who has not spoken" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Share the turns; invite quieter members.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING.M7_X_TT_NO_LINK', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING', 'Starts a new point without linking to what was said.', '{"question":"Juma says peer pressure leads to drugs. Your turn.","wrong_answer":"Drugs are bad.","correct_answer":"Building on Juma''s point, peer pressure is strongest at parties."}'::jsonb, 'Turns are seen as separate speeches.', 'Offer "Drugs are bad." beside "Building on Juma''s point, peer pressure is strongest at parties." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link to the last speaker first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING.M7_X_TT_SILENT', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING', 'Never takes a turn.', '{"question":"How can you join the discussion?","wrong_answer":"stay quiet","correct_answer":"wait for a pause and say \"May I add ...\""}'::jsonb, 'Shyness or fear of being wrong.', 'Offer "stay quiet" beside "wait for a pause and say "May I add ..."" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use a starter phrase to join.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING.M7_X_TT_INTERRUPTS', 'ENGL.G7.LISTEN.T6_CONVERSATION_SKILLS.TURN_TAKING', 'Cuts across others mid-sentence.', '{"question":"When do you take your turn?","wrong_answer":"as soon as I think of something","correct_answer":"at a pause, after the speaker finishes"}'::jsonb, 'Eagerness.', 'Offer "as soon as I think of something" beside "at a pause, after the speaker finishes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M7_X_RF_NO_PHRASING', 'ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Reads word by word.', '{"question":"Read: Drug abuse destroys families and dreams.","wrong_answer":"Drug. abuse. destroys.","correct_answer":"Drug abuse / destroys families / and dreams."}'::jsonb, 'Attention is on each word.', 'Offer "Drug. abuse. destroys." beside "Drug abuse / destroys families / and dreams." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read in phrases.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M7_X_RF_IGNORES_PUNCTUATION', 'ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Reads through commas and full stops.', '{"question":"Read: He refused, and his friends left. He was alone.","wrong_answer":"no pauses","correct_answer":"short pause at the comma, longer at the full stop"}'::jsonb, 'Punctuation is not linked to the voice.', 'Offer "no pauses" beside "short pause at the comma, longer at the full stop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pause at punctuation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M7_X_RF_FLAT', 'ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Reads with a flat voice.', '{"question":"Read: \"Never!\" she shouted.","wrong_answer":"flat","correct_answer":"strong, loud"}'::jsonb, 'Expression is not linked to meaning.', 'Offer "flat" beside "strong, loud" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let the voice show the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M7_X_RF_TOO_FAST', 'ENGL.G7.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Reads too fast and slurs words.', '{"question":"Read the paragraph at the right speed.","wrong_answer":"very fast, words run together","correct_answer":"steady, clear pace"}'::jsonb, 'Speed is mistaken for fluency.', 'Offer "very fast, words run together" beside "steady, clear pace" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read at speaking pace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS.M7_AK_TIME_MANNER', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS', 'Calls an adverb of time an adverb of manner, or the other way round.', '{"question":"In \"She arrived yesterday\", what does yesterday tell us.","wrong_answer":"how","correct_answer":"when"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "how" next to the right answer in a new sentence and ask again.', 'Ask: when, where or how? Yesterday answers when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS.M7_AK_PLACE_TIME', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS', 'Calls an adverb of place an adverb of time (here, outside).', '{"question":"In \"The children played outside\", what does outside tell us.","wrong_answer":"when","correct_answer":"where"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "when" next to the right answer in a new sentence and ask again.', 'Outside tells where the children played.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS.M7_AK_ADJECTIVE_ADVERB', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS', 'Names an adjective or a noun as the adverb of the sentence.', '{"question":"Find the adverb: \"The old man walked slowly.\"","wrong_answer":"old","correct_answer":"slowly"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "old" next to the right answer in a new sentence and ask again.', 'An adverb tells about the verb. Slowly tells how he walked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS.M7_AK_MANNER_PLACE', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_KINDS', 'Calls a word that tells how an adverb of place, because it comes after the verb.', '{"question":"In \"He answered politely\", what does politely tell us.","wrong_answer":"where","correct_answer":"how"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "where" next to the right answer in a new sentence and ask again.', 'Politely tells how he answered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM.M7_AF_GOOD_WELL', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM', 'Uses good as an adverb (She sings good).', '{"question":"Achieng sings very ___.","wrong_answer":"good","correct_answer":"well"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "good" next to the right answer in a new sentence and ask again.', 'Good describes a noun. Well describes how someone does something.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM.M7_AF_FASTLY', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM', 'Adds -ly to fast, hard or late (fastly, lately for late).', '{"question":"The matatu was going very ___.","wrong_answer":"fastly","correct_answer":"fast"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fastly" next to the right answer in a new sentence and ask again.', 'Fast is both an adjective and an adverb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM.M7_AF_HARDLY', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM', 'Uses hardly for hard (She studies hardly).', '{"question":"Njoroge studied ___ for the examination.","wrong_answer":"hardly","correct_answer":"hard"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hardly" next to the right answer in a new sentence and ask again.', 'Hardly means almost not at all. Hard means with a lot of effort.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM.M7_AF_ADJECTIVE_AFTER_VERB', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM', 'Uses an adjective after an action verb (He spoke quiet, she walks slow).', '{"question":"The teacher spoke ___ to the class.","wrong_answer":"quiet","correct_answer":"quietly"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "quiet" next to the right answer in a new sentence and ask again.', 'An action verb is described by an adverb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM.M7_AF_SPELL_LY', 'ENGL.G7.GRAMMA.T6_WORD_CLASSES_ADVERBS.ADVERB_FORM', 'Spells the -ly form wrongly (happyly, easyly, truely).', '{"question":"The boy answered the question ___. (easy)","wrong_answer":"easyly","correct_answer":"easily"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "easyly" next to the right answer in a new sentence and ask again.', 'After a consonant, y changes to i before -ly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS.M7_MS_IE_EI', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS', 'Mixes up ie and ei (beleive, freind, recieve).', '{"question":"My best ___ lives in Kisii.","wrong_answer":"freind","correct_answer":"friend"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "freind" next to the right answer in a new sentence and ask again.', 'Friend has i before e: fri-end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS.M7_MS_DOUBLE_LETTER', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS', 'Doubles or fails to double a letter (adress, neccessary, begining).', '{"question":"Write your home ___ on the form.","wrong_answer":"adress","correct_answer":"address"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "adress" next to the right answer in a new sentence and ask again.', 'Address has two d and two s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS.M7_MS_SILENT_LETTER', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS', 'Leaves out a silent letter (Febuary, goverment, libary).', '{"question":"The class was born in ___.","wrong_answer":"Febuary","correct_answer":"February"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Febuary" next to the right answer in a new sentence and ask again.', 'Say it slowly: Feb-ru-ary has an r in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS.M7_MS_SOUND_SPELL', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS', 'Spells a word as it sounds (becuase, definately, beutiful).', '{"question":"I stayed home ___ I was sick.","wrong_answer":"becuase","correct_answer":"because"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "becuase" next to the right answer in a new sentence and ask again.', 'Break it up: be-cause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS.M7_MS_HOMOPHONE_FORM', 'ENGL.G7.WRITIN.T6_COMMONLY_MISSPELT_WO.MISSPELT_WORDS', 'Writes a sound-alike word with the wrong spelling (alot, wich, wensday).', '{"question":"Our class meets on ___.","wrong_answer":"Wensday","correct_answer":"Wednesday"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Wensday" next to the right answer in a new sentence and ask again.', 'Wednesday has a d that is not said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES.M7_X_LN_WHOLE_SENTENCES', 'ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES', 'Tries to write every word the speaker says.', '{"question":"How should you take notes on a talk?","wrong_answer":"write every sentence","correct_answer":"key words and numbers under headings"}'::jsonb, 'Notes are seen as dictation.', 'Offer "write every sentence" beside "key words and numbers under headings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write only key words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES.M7_X_LN_MISSES_SIGNALS', 'ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES', 'Misses details signalled by words like "first" and "the main reason".', '{"question":"The speaker says, \"The main reason forests matter is rain.\" Note?","wrong_answer":"forests","correct_answer":"main reason: rain"}'::jsonb, 'Signal words are not noticed.', 'Offer "forests" beside "main reason: rain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for signals: first, main, for example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES.M7_X_LN_NUMBERS_WRONG', 'ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES', 'Writes numbers or names wrongly.', '{"question":"The speaker says Kenya has 7 per cent forest cover. Note?","wrong_answer":"70 per cent","correct_answer":"7 per cent"}'::jsonb, 'Numbers are not checked.', 'Offer "70 per cent" beside "7 per cent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write numbers exactly; check them if repeated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES.M7_X_LN_NO_HEADINGS', 'ENGL.G7.LISTEN.T7_LISTENING_COMPREHENS.LISTENING_NOTES', 'Writes notes with no headings or order.', '{"question":"Your notes are one long list. Improve?","wrong_answer":"leave them","correct_answer":"add headings: uses, threats, solutions"}'::jsonb, 'Notes are written in the order heard, unsorted.', 'Offer "leave them" beside "add headings: uses, threats, solutions" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Group notes under headings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS.M7_VI_WRONG_VISUAL', 'ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS', 'Chooses the wrong visual for the information needed (a map to compare amounts).', '{"question":"Which visual best compares the number of learners in four classes.","wrong_answer":"a map","correct_answer":"a bar graph"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a map" next to the right answer in a new sentence and ask again.', 'A bar graph compares amounts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS.M7_VI_ROW_COLUMN', 'ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS', 'Reads the wrong row or column of a table.', '{"question":"Read the table. How many mangoes did Achieng sell on Tuesday.","wrong_answer":"the number for Monday","correct_answer":"the number in the Tuesday column for Achieng"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the number for Monday" next to the right answer in a new sentence and ask again.', 'Find the row for the person and the column for the day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS.M7_VI_TOTAL_PART', 'ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS', 'Gives a total when one part is asked, or one part when the total is asked.', '{"question":"Read the table. How many mangoes in all did Achieng sell.","wrong_answer":"one day only","correct_answer":"the sum of all the days"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "one day only" next to the right answer in a new sentence and ask again.', 'Add the days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS.M7_VI_KEY_TITLE', 'ENGL.G7.READIN.T7_INDEPENDENT_READING_.VISUALS', 'Does not read the title or the key before the data.', '{"question":"What should you read first in a chart.","wrong_answer":"the smallest number","correct_answer":"the title and the headings"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the smallest number" next to the right answer in a new sentence and ask again.', 'The title says what the chart is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS.M7_PP_OBJECT_SUBJECT', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS', 'Uses the object form as the subject (Me and Juma went; Him is tall).', '{"question":"___ and Juma went to the river.","wrong_answer":"Me","correct_answer":"I"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Me" next to the right answer in a new sentence and ask again.', 'Before a verb, the subject form is used: I went.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS.M7_PP_SUBJECT_OBJECT', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS', 'Uses the subject form as the object (Give the book to I; she saw he).', '{"question":"The teacher gave the prize to Atieno and ___.","wrong_answer":"I","correct_answer":"me"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "I" next to the right answer in a new sentence and ask again.', 'After to and other prepositions, the object form is used: to me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS.M7_PP_US_WE', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS', 'Uses us as a subject or we as an object (Us are going; give it to we).', '{"question":"The headteacher thanked ___ for the clean compound.","wrong_answer":"we","correct_answer":"us"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "we" next to the right answer in a new sentence and ask again.', 'Thanked needs an object: us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS.M7_PP_NUMBER', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS', 'Uses the wrong pronoun for number or gender (the girls ... he, the tree ... she).', '{"question":"Wanjiru has a younger brother. ___ is in Grade 3.","wrong_answer":"She","correct_answer":"He"}'::jsonb, 'In Kiswahili one pronoun serves he and she.', 'Offer "She" next to the right answer in a new sentence and ask again.', 'The brother is a boy, so he.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS.M7_PP_DOUBLE_SUBJECT', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.PERSONAL_PRONOUNS', 'Repeats the subject with a pronoun (My mother she is a nurse).', '{"question":"Which sentence is correct.","wrong_answer":"My mother she is a nurse.","correct_answer":"My mother is a nurse."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "My mother she is a nurse." next to the right answer in a new sentence and ask again.', 'Name the person once. The noun is the subject, so no pronoun is added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES.M7_PO_ITS_ITS', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES', 'Writes it''s for belonging, or its for it is.', '{"question":"The dog wagged ___ tail.","wrong_answer":"it''s","correct_answer":"its"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "it''s" next to the right answer in a new sentence and ask again.', 'It''s means it is. Belonging has no apostrophe: its tail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES.M7_PO_APOSTROPHE_PRONOUN', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES', 'Writes her''s, your''s, their''s or our''s.', '{"question":"This book is ___.","wrong_answer":"her''s","correct_answer":"hers"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "her''s" next to the right answer in a new sentence and ask again.', 'Possessive pronouns never take an apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES.M7_PO_MINE_MY', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES', 'Uses mine before a noun or my where nothing follows (This is my. That is mine book).', '{"question":"Is this your pencil? Yes, it is ___.","wrong_answer":"my","correct_answer":"mine"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "my" next to the right answer in a new sentence and ask again.', 'When no noun follows, use mine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES.M7_PO_SUBJECT_FOR_POSSESSIVE', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES', 'Uses a subject pronoun to show belonging (Me book, he bag, they teacher).', '{"question":"The boys left ___ bags in the classroom.","wrong_answer":"they","correct_answer":"their"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "they" next to the right answer in a new sentence and ask again.', 'Belonging before a noun uses their.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES.M7_PO_THEIR_THERE', 'ENGL.G7.GRAMMA.T7_PERSONAL_AND_POSSESS.POSSESSIVES', 'Mixes up their, there and they''re.', '{"question":"The girls took ___ lunch to the field.","wrong_answer":"there","correct_answer":"their"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "there" next to the right answer in a new sentence and ask again.', 'Their shows belonging. There shows a place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS.M7_WP_EDIT_FIRST', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS', 'Puts editing before drafting.', '{"question":"What do you do first when you write a composition.","wrong_answer":"edit it","correct_answer":"plan it"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "edit it" next to the right answer in a new sentence and ask again.', 'You cannot edit what you have not written. Planning comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS.M7_WP_REVISE_EDIT', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS', 'Mixes up revising and editing.', '{"question":"At which step do you check spelling and punctuation.","wrong_answer":"revising","correct_answer":"editing"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "revising" next to the right answer in a new sentence and ask again.', 'Revising changes ideas and order. Editing corrects spelling and punctuation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS.M7_WP_DRAFT_FINAL', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS', 'Thinks the first draft is the final copy.', '{"question":"What is a first draft.","wrong_answer":"the final clean copy","correct_answer":"a first try that will be improved"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the final clean copy" next to the right answer in a new sentence and ask again.', 'A draft is a first try.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS.M7_WP_PUBLISH_FIRST', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.WRITING_PROCESS', 'Puts publishing in the middle.', '{"question":"Which step comes last.","wrong_answer":"planning","correct_answer":"publishing"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "planning" next to the right answer in a new sentence and ask again.', 'Publishing is sharing the finished work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION.M7_X_NC_NO_PLAN', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION', 'Writes straight away with no plan or draft.', '{"question":"What is the first step?","wrong_answer":"write the fair copy","correct_answer":"plan"}'::jsonb, 'Time pressure.', 'Offer "write the fair copy" beside "plan" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan, draft, revise, edit, then write the fair copy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION.M7_X_NC_IDIOM_MISUSE', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION', 'Uses an idiom with the wrong meaning.', '{"question":"Is \"He let the cat out of the bag\" right for \"He freed his cat\"?","wrong_answer":"Yes","correct_answer":"No: it means he told a secret"}'::jsonb, 'Idioms are read literally.', 'Offer "Yes" beside "No: it means he told a secret" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an idiom only for its real meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION.M7_X_NC_WEAK_INTRO', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION', 'Starts with a dull or unrelated introduction.', '{"question":"Better start for a story about a hero?","wrong_answer":"I woke up and brushed my teeth.","correct_answer":"The river was rising fast when Wanjiru heard the cry."}'::jsonb, 'A memorised opening.', 'Offer "I woke up and brushed my teeth." beside "The river was rising fast when Wanjiru heard the cry." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Begin near the action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION.M7_X_NC_SELF_ASSESS_SPELLING', 'ENGL.G7.WRITIN.T7_COMPOSITION_THE_WRIT.NARRATIVE_COMPOSITION', 'Self-assesses only spelling.', '{"question":"Assess your story.","wrong_answer":"Two spellings wrong.","correct_answer":"Introduction sets the scene; the body needs a clearer problem."}'::jsonb, 'Correctness is the only thing checked.', 'Offer "Two spellings wrong." beside "Introduction sets the scene; the body needs a clearer problem." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Assess introduction, body and conclusion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS.M7_PR_AT_ON_IN_TIME', 'ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS', 'Chooses the wrong one of at, on and in for a time (at Monday, in 5 o''clock).', '{"question":"The meeting starts ___ Monday.","wrong_answer":"at","correct_answer":"on"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "at" next to the right answer in a new sentence and ask again.', 'On for days, at for clock times, in for months and years.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS.M7_PR_TO_IN_PLACE', 'ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS', 'Uses to where in is needed, or in where to is needed (She is going in school, he is to Nairobi).', '{"question":"We are going ___ the market.","wrong_answer":"in","correct_answer":"to"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "in" next to the right answer in a new sentence and ask again.', 'To shows the direction of movement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS.M7_PR_KIND', 'ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS', 'Names a preposition of place as one of time or direction.', '{"question":"In \"The cat is under the table\", what does under tell us.","wrong_answer":"time","correct_answer":"place"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "time" next to the right answer in a new sentence and ask again.', 'Under tells where the cat is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS.M7_PR_ON_AT_PLACE', 'ENGL.G7.GRAMMA.T8_SIMPLE_PREPOSITIONS.PREPOSITIONS', 'Uses on where at is needed for a place (on the bus stop, in the gate).', '{"question":"Please wait for me ___ the bus stop.","wrong_answer":"on","correct_answer":"at"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "on" next to the right answer in a new sentence and ask again.', 'At is for a point or a place we wait at.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE.M7_AN_PART_MIX', 'ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE', 'Mixes up what the introduction, the body and the conclusion do.', '{"question":"Which part of a narrative tells who, where and when.","wrong_answer":"the conclusion","correct_answer":"the introduction"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the conclusion" next to the right answer in a new sentence and ask again.', 'The introduction opens the story and sets the scene.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE.M7_AN_SPELLING_ONLY', 'ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE', 'Thinks assessing a composition is only counting words or checking spelling.', '{"question":"What is the first step when you assess your own composition.","wrong_answer":"count the words","correct_answer":"read it again slowly"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "count the words" next to the right answer in a new sentence and ask again.', 'Assessing starts by reading with care.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE.M7_AN_SKIP_READ', 'ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE', 'Hands in a composition without reading it again.', '{"question":"What should you do before you hand in your composition.","wrong_answer":"hand it in at once","correct_answer":"read it again and check each part"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hand it in at once" next to the right answer in a new sentence and ask again.', 'Always read your work again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE.M7_X_AN_TITLE_FIT', 'ENGL.G7.WRITIN.T8_COMPOSITION_WRITING_.ASSESS_NARRATIVE', 'Does not check that the title fits the story.', '{"question":"Title \"My Best Day\"; the story is about a lost dog. Fit?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'The title is not checked.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check that the title fits the whole story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS.M7_SV_SPELLING_SAME', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS', 'Judges the vowel sound by the spelling (look and food both have oo).', '{"question":"Which word has the same vowel sound as \"put\" (/ʊ/).","wrong_answer":"food","correct_answer":"look"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "food" next to the right answer in a new sentence and ask again.', 'Say the words aloud. Put and look have the short sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS.M7_SV_SHORT_LONG', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS', 'Mixes the short /ʊ/ and the long /uː/ sound.', '{"question":"Which word has the long vowel sound of \"pool\" (/uː/).","wrong_answer":"pull","correct_answer":"room"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "pull" next to the right answer in a new sentence and ask again.', 'The /uː/ sound is longer: pool, room, moon, fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS.M7_SV_ODD_ONE', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS', 'Cannot find the word with a different vowel sound.', '{"question":"Which word has a different vowel sound: book, good, moon, foot.","wrong_answer":"book","correct_answer":"moon"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "book" next to the right answer in a new sentence and ask again.', 'Say each word. Three have the short sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS.M7_X_SV_DIPHTHONG', 'ENGL.G7.LISTEN.T9_PRONUNCIATION_CONSON.SOUNDS_VOWELS', 'Hears a diphthong as a pure vowel.', '{"question":"Which has the same vowel as \"boat\": bought or note?","wrong_answer":"bought","correct_answer":"note"}'::jsonb, 'Diphthongs are heard as one vowel.', 'Offer "bought" beside "note" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Boat and note slide; bought does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC.M7_CB_AND_BUT', 'ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC', 'Uses and where but is needed (She is small and strong).', '{"question":"Njeri is small ___ very strong.","wrong_answer":"and","correct_answer":"but"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "and" next to the right answer in a new sentence and ask again.', 'But shows that the two ideas do not go together as expected.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC.M7_CB_OR_AND', 'ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC', 'Uses or where and is needed, or and where or is needed.', '{"question":"Would you like tea ___ coffee?","wrong_answer":"and","correct_answer":"or"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "and" next to the right answer in a new sentence and ask again.', 'A choice is joined by or.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC.M7_CB_BUT_AND_DOUBLE', 'ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC', 'Uses two joining words together (But and, and but, or but).', '{"question":"He was tired ___ he finished the work.","wrong_answer":"but and","correct_answer":"but"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "but and" next to the right answer in a new sentence and ask again.', 'One joining word is enough between two parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC.M7_CB_COMMA_JOIN', 'ENGL.G7.GRAMMA.T9_CONJUNCTIONS.CONJUNCTIONS_BASIC', 'Joins two sentences with only a comma (It was late, we went home).', '{"question":"Which sentence is correct.","wrong_answer":"It was late, we went home.","correct_answer":"It was late, so we went home."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "It was late, we went home." next to the right answer in a new sentence and ask again.', 'A comma alone cannot join two sentences; add a joining word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER.M7_SO_REVERSED', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER', 'Puts the events in the opposite order.', '{"question":"Which list shows the events in the order they happened.","wrong_answer":"the events backwards","correct_answer":"the events as they happened"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the events backwards" next to the right answer in a new sentence and ask again.', 'Find the first event in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER.M7_SO_SWAPPED', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER', 'Swaps two neighbouring events.', '{"question":"Which list shows the events in the order they happened.","wrong_answer":"two events swapped","correct_answer":"the events as they happened"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "two events swapped" next to the right answer in a new sentence and ask again.', 'Check each pair of events: which came first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER.M7_SO_ROTATED', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER', 'Starts with the last event or the one that opens the story.', '{"question":"Which list shows the events in the order they happened.","wrong_answer":"the last event first","correct_answer":"the events as they happened"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the last event first" next to the right answer in a new sentence and ask again.', 'The story begins with the opening event.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER.M7_X_SO_FLASHBACK', 'ENGL.G7.READIN.T9_INTENSIVE_READING_CL.STORY_ORDER', 'Orders events by when they are told, not when they happened, in a flashback.', '{"question":"The story starts at the end and goes back. What happened first?","wrong_answer":"what was told first","correct_answer":"the event told in the flashback"}'::jsonb, 'Order of telling is mistaken for order of events.', 'Offer "what was told first" beside "the event told in the flashback" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use time clues: years earlier, before that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES.M7_NF_NARRATIVE_DESCRIPTION', 'ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES', 'Calls a description of a place or a person a narrative.', '{"question":"Which text is a narrative.","wrong_answer":"The market is wide, noisy and full of colour.","correct_answer":"On Saturday Achieng lost her purse in the market and had to find it."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The market is wide, noisy and full of colour." next to the right answer in a new sentence and ask again.', 'A narrative tells what happened: events in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES.M7_NF_MISSING_PART', 'ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES', 'Does not notice what a story lacks (the problem, the setting or the ending).', '{"question":"This story has characters and a setting but no problem. What is missing.","wrong_answer":"a title","correct_answer":"a problem or conflict"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a title" next to the right answer in a new sentence and ask again.', 'A story needs something to go wrong or to be solved.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES.M7_NF_SETTING_CHARACTER', 'ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES', 'Names a character as the setting or the setting as a character.', '{"question":"What is the setting of a story.","wrong_answer":"the people in the story","correct_answer":"the time and place of the story"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the people in the story" next to the right answer in a new sentence and ask again.', 'Setting means where and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES.M7_NF_PERSON', 'ENGL.G7.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_FEATURES', 'Writes a narrative in the present tense, or mixes I and he in the same story.', '{"question":"Which opening is a narrative told in the past.","wrong_answer":"I am walking to the river.","correct_answer":"I walked to the river early in the morning."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "I am walking to the river." next to the right answer in a new sentence and ask again.', 'A story about what happened is told in the past tense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES.M7_SF_OCCASION', 'ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES', 'Takes an occasion that does not need a speech.', '{"question":"At which of these would a speech most likely be given.","wrong_answer":"a private chat with a friend","correct_answer":"a school prize-giving day"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a private chat with a friend" next to the right answer in a new sentence and ask again.', 'A speech is for an audience at an occasion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES.M7_SF_PART_ORDER', 'ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES', 'Puts the parts of a speech in the wrong order (thanks first).', '{"question":"Which part of a speech comes first.","wrong_answer":"the thanks","correct_answer":"the greeting"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the thanks" next to the right answer in a new sentence and ask again.', 'You greet the audience first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES.M7_SF_READING', 'ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES', 'Thinks a speech is read with the eyes on the paper.', '{"question":"Which is good delivery of a speech.","wrong_answer":"reading it with your eyes on the paper","correct_answer":"looking at the audience and speaking clearly"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "reading it with your eyes on the paper" next to the right answer in a new sentence and ask again.', 'Speak to the people, not to the paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES.M7_SF_TONE', 'ENGL.G7.LISTEN.T10_ORAL_PRESENTATIONS_D.SPEECH_FEATURES', 'Uses a tone that does not fit the occasion (joking at a funeral).', '{"question":"Which tone fits a funeral speech.","wrong_answer":"joking and loud","correct_answer":"respectful and calm"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "joking and loud" next to the right answer in a new sentence and ask again.', 'The tone must fit the occasion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M7_NM_DETAIL_MAIN', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Takes a detail for the main point.', '{"question":"Which is a main point of a text on recycling.","wrong_answer":"a bottle takes 450 years to break down","correct_answer":"recycling saves resources and cuts waste"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a bottle takes 450 years to break down" next to the right answer in a new sentence and ask again.', 'The main point covers the whole text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M7_NM_COPY', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Copies whole sentences as notes.', '{"question":"Which are the best notes.","wrong_answer":"a copy of every sentence","correct_answer":"key words and short phrases"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a copy of every sentence" next to the right answer in a new sentence and ask again.', 'Notes are short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M7_NM_MISS_MAIN', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Writes notes that leave out a main point.', '{"question":"Which notes keep all the main points.","wrong_answer":"only the first point","correct_answer":"all the main points in short form"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "only the first point" next to the right answer in a new sentence and ask again.', 'Check that every main point is there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M7_NM_ADDS', 'ENGL.G7.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Adds ideas to the notes that are not in the text.', '{"question":"Which note is faithful to the text.","wrong_answer":"a note with an idea added by the reader","correct_answer":"a note with only what the text says"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a note with an idea added by the reader" next to the right answer in a new sentence and ask again.', 'Notes record what the text says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES.M7_AR_A_AN_SOUND', 'ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'Chooses a or an by the letter, not the sound (an university, a hour).', '{"question":"Our teacher stayed for ___ hour after school.","wrong_answer":"a","correct_answer":"an"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a" next to the right answer in a new sentence and ask again.', 'Say the word: hour starts with a vowel sound, so an.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES.M7_AR_A_BEFORE_VOWEL', 'ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'Uses a before a vowel (a apple, a orange).', '{"question":"She ate ___ orange after lunch.","wrong_answer":"a","correct_answer":"an"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a" next to the right answer in a new sentence and ask again.', 'Orange starts with a vowel sound, so an.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES.M7_AR_THE_GENERAL', 'ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'Uses the before a general idea or plural (The life is hard; I like the mangoes).', '{"question":"We should protect ___ environment.","wrong_answer":"a","correct_answer":"the"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a" next to the right answer in a new sentence and ask again.', 'The environment around us is one known thing, so the.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES.M7_AR_NO_ARTICLE', 'ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'Leaves out a, an or the where one is needed (She is teacher).', '{"question":"My aunt is ___ nurse at the hospital.","wrong_answer":"no word","correct_answer":"a"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "no word" next to the right answer in a new sentence and ask again.', 'A job needs a: a nurse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES.M7_AR_FIRST_MENTION', 'ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'Uses the for the first mention and a for the second.', '{"question":"A boy found a purse. ___ boy gave it to the teacher.","wrong_answer":"A","correct_answer":"The"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "A" next to the right answer in a new sentence and ask again.', 'The boy is the one already mentioned.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES.M7_AR_WRONG_WORD', 'ENGL.G7.GRAMMA.T10_DETERMINERS.ARTICLES', 'Uses a word that does not go with one thing (many, these) where a, an or the is needed.', '{"question":"There was ___ egg on the table.","wrong_answer":"many","correct_answer":"an"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "many" next to the right answer in a new sentence and ask again.', 'A single thing needs a, an or the.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING.M7_LG_WRONG_GROUP', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING', 'Puts an item under the wrong heading.', '{"question":"Which item belongs under \"Food\" in a packing list.","wrong_answer":"torch","correct_answer":"bread"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "torch" next to the right answer in a new sentence and ask again.', 'Food is for eating.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING.M7_LG_ODD_ITEM', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING', 'Does not see which item does not belong to the group.', '{"question":"Which item does not belong with the others: pen, ruler, pencil, soap.","wrong_answer":"ruler","correct_answer":"soap"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "ruler" next to the right answer in a new sentence and ask again.', 'Three are stationery.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING.M7_LG_EVENT_FIT', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING', 'Chooses items that do not fit the event.', '{"question":"Which list fits a day at the beach.","wrong_answer":"school bag, books, ruler","correct_answer":"swimming costume, towel, sunscreen"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "school bag, books, ruler" next to the right answer in a new sentence and ask again.', 'Think about what the event needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING.M7_LG_QUANTITY', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LIST_GROUPING', 'Leaves out the amount in a shopping list (sugar, flour, rice with no amounts).', '{"question":"Which shopping list entry is best.","wrong_answer":"sugar","correct_answer":"2 kg of sugar"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "sugar" next to the right answer in a new sentence and ask again.', 'A shopping list says how much to buy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE.M7_X_LS_NO_QUANTITY', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE', 'Writes shopping items with no quantities.', '{"question":"Shopping list for a class party: \"sugar\".","wrong_answer":"sugar","correct_answer":"2 kg sugar"}'::jsonb, 'The writer knows the amount and forgets the reader does not.', 'Offer "sugar" beside "2 kg sugar" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add quantities.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE.M7_X_LS_NOT_NEEDED', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE', 'Packs items the event does not need.', '{"question":"Packing for a music festival: which is not needed?","wrong_answer":"school timetable","correct_answer":"raincoat"}'::jsonb, 'Every item that comes to mind is listed.', 'Offer "school timetable" beside "raincoat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: will I use it at this event?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE.M7_X_LS_NO_GROUPS', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE', 'Lists items in no groups.', '{"question":"Improve: shirt, bread, ID, socks, milk.","wrong_answer":"leave it","correct_answer":"Clothes: shirt, socks. Food: bread, milk. Documents: ID."}'::jsonb, 'Grouping is not seen as useful.', 'Offer "leave it" beside "Clothes: shirt, socks. Food: bread, milk. Documents: ID." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Group items by kind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE.M7_X_LS_SENTENCES', 'ENGL.G7.WRITIN.T10_FUNCTIONAL_WRITING_P.LISTS_WRITE', 'Writes the list as sentences.', '{"question":"Which is a list?","wrong_answer":"I will carry a shirt and also socks.","correct_answer":"shirt\nsocks"}'::jsonb, 'Composition habits.', 'Offer "I will carry a shirt and also socks." beside "shirt
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW.M7_IN_REASON', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW', 'Gives a wrong reason for an interview.', '{"question":"Why might a learner sit an interview.","wrong_answer":"to watch a film","correct_answer":"to join a school or win a scholarship"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "to watch a film" next to the right answer in a new sentence and ask again.', 'An interview tests whether you are suited to a place or job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW.M7_IN_SHORT_ANSWER', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW', 'Answers with one word (Yes. No.).', '{"question":"The panel asks: \"Why do you want to join this school?\" Which answer is best.","wrong_answer":"Because.","correct_answer":"I want to join because the school has a good library and I love reading."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Because." next to the right answer in a new sentence and ask again.', 'Give a reason in a full sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW.M7_IN_CLARIFY', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW', 'Says nothing, or says What?, when a question is not clear.', '{"question":"You did not hear a question. What is the polite thing to say.","wrong_answer":"What?","correct_answer":"Could you please repeat the question?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "What?" next to the right answer in a new sentence and ask again.', 'Ask politely for clarification.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW.M7_IN_CONFIDENT', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_KNOW', 'Thinks a confident answer is a boastful or a rude one.', '{"question":"Which answer is confident and polite.","wrong_answer":"I am the best, nobody is better than me.","correct_answer":"I work hard and I am ready to learn."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "I am the best, nobody is better than me." next to the right answer in a new sentence and ask again.', 'Be confident but modest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK.M7_X_IS_BOASTFUL', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK', 'Answers boastfully.', '{"question":"Why should we give you a place?","wrong_answer":"I am the best; nobody can beat me.","correct_answer":"I work hard and I scored well in Science."}'::jsonb, 'Confidence is confused with boasting.', 'Offer "I am the best; nobody can beat me." beside "I work hard and I scored well in Science." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Show confidence with facts, not boasts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK.M7_X_IS_ONE_WORD', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK', 'Answers in one word.', '{"question":"Do you like Mathematics?","wrong_answer":"Yes.","correct_answer":"Yes, I like it because I enjoy solving problems."}'::jsonb, 'Short classroom answers.', 'Offer "Yes." beside "Yes, I like it because I enjoy solving problems." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer and give a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK.M7_X_IS_MUMBLES', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK', 'Speaks too softly or mumbles.', '{"question":"How should you speak to a panel?","wrong_answer":"quietly, looking down","correct_answer":"clearly, looking at the panel"}'::jsonb, 'Nerves.', 'Offer "quietly, looking down" beside "clearly, looking at the panel" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sit up, look at the panel, speak clearly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK.M7_X_IS_NO_CLARIFY', 'ENGL.G7.LISTEN.T11_INTERVIEWS.INTERVIEW_SPEAK', 'Guesses at a question instead of asking for clarification.', '{"question":"You did not understand the question. What do you do?","wrong_answer":"answer anything","correct_answer":"Could you please repeat the question?"}'::jsonb, 'Asking is seen as weakness.', 'Offer "answer anything" beside "Could you please repeat the question?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask politely for the question again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION.M7_AF2_NOUN_FOR_ADJ', 'ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION', 'Uses the noun where the adjective is needed (a danger road, a beauty girl).', '{"question":"It is a ___ road at night.","wrong_answer":"danger","correct_answer":"dangerous"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "danger" next to the right answer in a new sentence and ask again.', 'Before a noun, an adjective is needed: dangerous.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION.M7_AF2_WRONG_SUFFIX', 'ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION', 'Adds the wrong ending (carely, helpness, hopeable).', '{"question":"The nurse was very ___ with the baby. (care)","wrong_answer":"carely","correct_answer":"careful"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "carely" next to the right answer in a new sentence and ask again.', 'Careful means full of care.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION.M7_AF2_SPELL_CHANGE', 'ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION', 'Keeps the spelling of the noun (beautyful, easyer, fameous).', '{"question":"The young girl was very ___.","wrong_answer":"beautyful","correct_answer":"beautiful"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "beautyful" next to the right answer in a new sentence and ask again.', 'Y changes to i before -ful: beauty, beautiful.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION.M7_AF2_FUL_LESS', 'ENGL.G7.GRAMMA.T11_FORMATION_OF_ADJECTI.ADJECTIVE_FORMATION', 'Mixes up -ful and -less (a harmful medicine used for a harmless one).', '{"question":"The old knife is ___ because it cannot cut. (use)","wrong_answer":"useful","correct_answer":"useless"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "useful" next to the right answer in a new sentence and ask again.', 'Cannot cut means without use: useless.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA.M7_DL_LESSON_ENDING', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA', 'Thinks a dilemma narrative ends with a lesson told by the narrator.', '{"question":"How does a dilemma narrative end.","wrong_answer":"with the narrator telling the lesson","correct_answer":"with a hard question to the listener"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "with the narrator telling the lesson" next to the right answer in a new sentence and ask again.', 'A dilemma leaves the choice to the listeners.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA.M7_DL_CLOSING_FORMULA', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA', 'Picks a question that is not a closing formula.', '{"question":"Which is a closing formula of a dilemma narrative.","wrong_answer":"What time is it?","correct_answer":"Who do you think was right?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "What time is it?" next to the right answer in a new sentence and ask again.', 'It asks the listener to choose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA.M7_DL_NO_DILEMMA', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA', 'Thinks any story with two characters is a dilemma.', '{"question":"Which story is a dilemma narrative.","wrong_answer":"a story with an easy ending","correct_answer":"a story where both choices are hard"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a story with an easy ending" next to the right answer in a new sentence and ask again.', 'A dilemma has two hard choices.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA.M7_X_DL_EASY_ANSWER', 'ENGL.G7.READIN.T11_INTENSIVE_READING_DI.DILEMMA', 'Gives the dilemma an easy answer the story does not support.', '{"question":"Which son should inherit the land? (both deserve it)","wrong_answer":"the eldest, of course","correct_answer":"it is hard: give reasons for one"}'::jsonb, 'The child thinks a story must have one right answer.', 'Offer "the eldest, of course" beside "it is hard: give reasons for one" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A dilemma has no easy answer; argue with reasons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS.M7_SY_RELATED_NOT_SAME', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS', 'Gives a related word instead of a synonym (big for huge is right, but big for building is not).', '{"question":"Which word means the same as \"tiny\".","wrong_answer":"small","correct_answer":"minute"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "small" next to the right answer in a new sentence and ask again.', 'A synonym can replace the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS.M7_SY_ANT_SYN', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS', 'Gives a synonym when an antonym is asked, or the other way round.', '{"question":"Which word is the opposite of \"ancient\".","wrong_answer":"old","correct_answer":"modern"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "old" next to the right answer in a new sentence and ask again.', 'An antonym has the opposite meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS.M7_SY_PREFIX_ANT', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS', 'Makes an antonym only by adding un- or not (unhot, not-big).', '{"question":"The opposite of \"generous\" is ___.","wrong_answer":"ungenerous","correct_answer":"selfish"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "ungenerous" next to the right answer in a new sentence and ask again.', 'Not every antonym is made with un-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS.M7_SY_CONTEXT', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.SYNONYMS_ANTONYMS', 'Chooses a synonym that does not fit the sentence.', '{"question":"Which word can replace \"bright\" in \"She is a bright pupil\".","wrong_answer":"shiny","correct_answer":"clever"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "shiny" next to the right answer in a new sentence and ask again.', 'A word can have more than one meaning. Check which meaning fits the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS.M7_NW_FORTY', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'Spells forty as fourty or fourteen as forteen.', '{"question":"Write 40 in words.","wrong_answer":"fourty","correct_answer":"forty"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fourty" next to the right answer in a new sentence and ask again.', 'Forty has no u, but four and fourteen have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS.M7_NW_ORDINAL', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'Writes an ordinal with the wrong ending (1th, 2th, 3th, twenty-oneth).', '{"question":"Our school sports day is on the 22___ of May.","wrong_answer":"22th","correct_answer":"22nd"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "22th" next to the right answer in a new sentence and ask again.', 'Numbers ending in 2 take nd.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS.M7_NW_HYPHEN', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'Leaves out the hyphen in twenty-one to ninety-nine.', '{"question":"Write 45 in words.","wrong_answer":"forty five","correct_answer":"forty-five"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "forty five" next to the right answer in a new sentence and ask again.', 'Join the two words with a hyphen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS.M7_NW_EIGHTH', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'Spells the ordinal wrongly (eigth, nineth, twelvth).', '{"question":"He finished in ___ place.","wrong_answer":"eigth","correct_answer":"eighth"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "eigth" next to the right answer in a new sentence and ask again.', 'Eighth has two h, one in eigh and one in th.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS.M7_NW_START_FIGURE', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'Begins a sentence with a figure (40 learners came).', '{"question":"Which sentence is correct.","wrong_answer":"40 learners came to the meeting.","correct_answer":"Forty learners came to the meeting."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "40 learners came to the meeting." next to the right answer in a new sentence and ask again.', 'Never begin a sentence with a figure.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS.M7_NW_SPELL_NUMBER', 'ENGL.G7.WRITIN.T11_SPELLING_ANTONYMS_SY.NUMBER_WORDS', 'Spells a number word wrongly (ninty, fourty, forteen).', '{"question":"Write 90 in words.","wrong_answer":"ninty","correct_answer":"ninety"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "ninty" next to the right answer in a new sentence and ask again.', 'Ninety has an e before ty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES.M7_OP_FACT', 'ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES', 'Takes a fact for an opinion, or an opinion for a fact.', '{"question":"Which sentence gives an opinion.","wrong_answer":"Kenya has 47 counties.","correct_answer":"In my opinion, football is the best sport."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Kenya has 47 counties." next to the right answer in a new sentence and ask again.', 'An opinion shows what someone thinks or feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES.M7_OP_PHRASE', 'ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES', 'Chooses a phrase that does not show a view (First, finally, however).', '{"question":"Which expression shows your view.","wrong_answer":"First of all","correct_answer":"I believe that"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "First of all" next to the right answer in a new sentence and ask again.', 'These words say what you think.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES.M7_OP_RUDE_DISAGREE', 'ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES', 'Disagrees rudely (That is wrong, you know nothing).', '{"question":"Which is a polite way to disagree.","wrong_answer":"That is nonsense.","correct_answer":"I see your point, but I think differently."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "That is nonsense." next to the right answer in a new sentence and ask again.', 'Respect the other person while you disagree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES.M7_OP_NO_REASON', 'ENGL.G7.LISTEN.T12_LISTENING_VIEWS_OPIN.OPINION_PHRASES', 'Gives a view with no reason.', '{"question":"Which gives a view with a reason.","wrong_answer":"I think school uniform is bad.","correct_answer":"I think school uniform is good because it makes all learners look equal."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "I think school uniform is bad." next to the right answer in a new sentence and ask again.', 'Give a reason after the view.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG.M7_PV_PUT_OFF_OUT', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG', 'Mixes up put off, put out and put on.', '{"question":"The firefighters ___ the fire in the market.","wrong_answer":"put off","correct_answer":"put out"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "put off" next to the right answer in a new sentence and ask again.', 'Put out means to stop a fire. Put off means to delay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG.M7_PV_GIVE_UP_IN', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG', 'Mixes up give up, give in and give away.', '{"question":"The thief refused to ___ and run away.","wrong_answer":"give away","correct_answer":"give up"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "give away" next to the right answer in a new sentence and ask again.', 'Give up means to stop trying. Give away means to give for free.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG.M7_PV_COME_ACROSS', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG', 'Reads the phrasal verb word for word (come across means to cross).', '{"question":"While cleaning, Ouma ___ an old photograph.","wrong_answer":"came out","correct_answer":"came across"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "came out" next to the right answer in a new sentence and ask again.', 'Come across means to find by chance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG.M7_PV_WRONG_PARTICLE', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG', 'Uses the wrong little word (come out with an idea for come up with an idea).', '{"question":"The class tried to ___ a good name for the club.","wrong_answer":"come out with","correct_answer":"come up with"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "come out with" next to the right answer in a new sentence and ask again.', 'Come up with means to think of something.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG.M7_PV_LITERAL_PUT', 'ENGL.G7.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_PCG', 'Reads put on as put something on top (put on a jacket as place a jacket).', '{"question":"It was cold, so Baraka ___ his jacket.","wrong_answer":"put out","correct_answer":"put on"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "put out" next to the right answer in a new sentence and ask again.', 'Put on means to wear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT.M7_DF_QUOTES_EVERY_LINE', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT', 'Writes a play-style dialogue with quotation marks round every line.', '{"question":"Which is the correct play-style dialogue.","wrong_answer":"\"Atieno: Good morning.\" \"Juma: Good morning.\"","correct_answer":"Atieno: Good morning.\nJuma: Good morning."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer ""Atieno: Good morning." "Juma: Good morning."" next to the right answer in a new sentence and ask again.', 'In a script the speaker name and a colon show who is speaking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT.M7_DF_SAME_LINE', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT', 'Runs the speakers together on one line.', '{"question":"How should each speaker''s words be written.","wrong_answer":"on the same line","correct_answer":"on a new line"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "on the same line" next to the right answer in a new sentence and ask again.', 'Each turn starts on a new line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT.M7_DF_ACTIONS', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT', 'Writes actions without brackets so they look like spoken words.', '{"question":"How are actions such as smiling shown in a dialogue.","wrong_answer":"in quotation marks","correct_answer":"in brackets after the name"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "in quotation marks" next to the right answer in a new sentence and ask again.', 'Brackets show it is not spoken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT.M7_DF_NO_NAME', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_FORMAT', 'Leaves out the speaker''s name.', '{"question":"What does each line of a dialogue start with.","wrong_answer":"the words spoken","correct_answer":"the speaker''s name and a colon"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the words spoken" next to the right answer in a new sentence and ask again.', 'Without a name we do not know who speaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M7_X_DW_QUOTES', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Puts every line in quotation marks.', '{"question":"Set out: Atieno says good morning.","wrong_answer":"\"Atieno: Good morning.\"","correct_answer":"Atieno: Good morning."}'::jsonb, 'Direct speech rules are carried over.', 'Offer ""Atieno: Good morning."" beside "Atieno: Good morning." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A dialogue uses names and colons, no quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M7_X_DW_SAME_LINE', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Writes two speakers on the same line.', '{"question":"Where does the next speaker go?","wrong_answer":"on the same line","correct_answer":"on a new line"}'::jsonb, 'Space is saved.', 'Offer "on the same line" beside "on a new line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'New speaker, new line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M7_X_DW_ACTIONS', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Writes actions as speech.', '{"question":"Atieno smiles. How do you show it?","wrong_answer":"Atieno: smiles","correct_answer":"Atieno: (smiling) Good morning."}'::jsonb, 'Actions are not separated.', 'Offer "Atieno: smiles" beside "Atieno: (smiling) Good morning." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put actions in brackets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M7_X_DW_NO_PURPOSE', 'ENGL.G7.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Writes a dialogue that goes nowhere.', '{"question":"What should the dialogue about fashion do?","wrong_answer":"greetings only","correct_answer":"show the speakers sharing and resolving views"}'::jsonb, 'The dialogue is a chain of greetings.', 'Offer "greetings only" beside "show the speakers sharing and resolving views" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan what the speakers want and how it ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS.M7_TW_PERSON_PLACE', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS', 'Mixes a person and a place (conductor and terminus).', '{"question":"The matatu ___ collected the fares.","wrong_answer":"terminus","correct_answer":"conductor"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "terminus" next to the right answer in a new sentence and ask again.', 'The person who collects fares is the conductor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS.M7_TW_FARE_FEE', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS', 'Uses fare where another word is needed (school fare, bus fee).', '{"question":"The ___ from Nakuru to Eldoret is 400 shillings.","wrong_answer":"fee","correct_answer":"fare"}'::jsonb, 'Fee and fare are both used for payment.', 'Offer "fee" next to the right answer in a new sentence and ask again.', 'A fare is the money paid for a journey.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS.M7_TW_JOURNEY_TRIP', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS', 'Mixes journey, route and destination.', '{"question":"Kisumu is our final ___.","wrong_answer":"route","correct_answer":"destination"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "route" next to the right answer in a new sentence and ask again.', 'The place you are going to is the destination.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS.M7_TW_LUGGAGE', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS', 'Writes luggages or baggages.', '{"question":"The passengers put their ___ on the roof of the bus.","wrong_answer":"luggages","correct_answer":"luggage"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "luggages" next to the right answer in a new sentence and ask again.', 'Luggage is not counted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS.M7_TW_TIMETABLE', 'ENGL.G7.LISTEN.T13_LISTENING_COMPREHENS.TRAVEL_WORDS', 'Mixes timetable with ticket or route.', '{"question":"The bus ___ shows when each bus leaves.","wrong_answer":"ticket","correct_answer":"timetable"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "ticket" next to the right answer in a new sentence and ask again.', 'A timetable lists times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA.M7_MI_DETAIL', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA', 'Chooses one detail as the main idea.', '{"question":"What is the main idea of the passage.","wrong_answer":"a detail from one paragraph","correct_answer":"what the whole passage is about"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a detail from one paragraph" next to the right answer in a new sentence and ask again.', 'The main idea covers the whole passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA.M7_MI_TOO_BROAD', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA', 'Chooses an idea that is much wider than the passage.', '{"question":"What is the main idea of the passage.","wrong_answer":"a very wide statement","correct_answer":"a statement of the passage''s own topic"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a very wide statement" next to the right answer in a new sentence and ask again.', 'The main idea must fit this passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA.M7_MI_NOT_IN_TEXT', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA', 'Chooses an idea that is not in the passage.', '{"question":"What is the main idea of the passage.","wrong_answer":"an idea that is not in the passage","correct_answer":"an idea the passage holds"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an idea that is not in the passage" next to the right answer in a new sentence and ask again.', 'Check that the passage says it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA.M7_MI_DETAIL_FOR_ASKED', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.MAIN_IDEA', 'Gives a detail near the one asked for.', '{"question":"What was the thing the question asked for.","wrong_answer":"a nearby detail","correct_answer":"the exact detail asked for"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a nearby detail" next to the right answer in a new sentence and ask again.', 'Read the question word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY.M7_SU_ONE_DETAIL', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY', 'Gives one detail as the summary.', '{"question":"Which is the best summary of the passage.","wrong_answer":"one detail","correct_answer":"the key ideas in a few lines"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "one detail" next to the right answer in a new sentence and ask again.', 'A summary covers the whole passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY.M7_SU_COPIES_START', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY', 'Chooses the opening lines copied as the summary.', '{"question":"Which is the best summary of the passage.","wrong_answer":"the first lines copied","correct_answer":"a short account of the whole passage"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the first lines copied" next to the right answer in a new sentence and ask again.', 'A summary is in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY.M7_SU_ADDS', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY', 'Adds something the passage does not say.', '{"question":"Which is the best summary of the passage.","wrong_answer":"a summary with a new idea","correct_answer":"a summary with only the passage''s ideas"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a summary with a new idea" next to the right answer in a new sentence and ask again.', 'A summary adds nothing new.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY.M7_SU_ORDER', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.SUMMARY', 'Gets the order of the key ideas wrong.', '{"question":"Which summary keeps the ideas in the right order.","wrong_answer":"the ideas in a mixed order","correct_answer":"the ideas in the passage''s order"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the ideas in a mixed order" next to the right answer in a new sentence and ask again.', 'Keep the order of the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY.M7_IM_FACT_LINE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY', 'Picks a line that only gives a fact as the one that paints a picture.', '{"question":"Which line paints a picture.","wrong_answer":"a line that states a fact","correct_answer":"a line with sights, sounds or movement"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a line that states a fact" next to the right answer in a new sentence and ask again.', 'A picture line uses the senses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY.M7_IM_WRONG_PICTURE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY', 'Chooses a picture that the words do not make.', '{"question":"What does this line help you to see.","wrong_answer":"something the line does not show","correct_answer":"what the words show"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "something the line does not show" next to the right answer in a new sentence and ask again.', 'Use all the words in the line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY.M7_IM_LITERAL', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY', 'Reads a picture word for word (the clouds were wool as real wool).', '{"question":"What does the line mean.","wrong_answer":"a word-for-word meaning","correct_answer":"the picture the writer wants"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a word-for-word meaning" next to the right answer in a new sentence and ask again.', 'The writer compares to help you picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES.M7_CX_LOOKS_LIKE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES', 'Chooses a meaning from a word that looks like the hard word.', '{"question":"What does the word mean in the passage.","wrong_answer":"a meaning from a similar-looking word","correct_answer":"a meaning the sentence supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a meaning from a similar-looking word" next to the right answer in a new sentence and ask again.', 'Use the sentence, not the look of the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES.M7_CX_COMMON_MEANING', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES', 'Uses the common meaning of a word that has another meaning here.', '{"question":"What does the word mean in the passage.","wrong_answer":"its common meaning","correct_answer":"its meaning here"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "its common meaning" next to the right answer in a new sentence and ask again.', 'Try the meaning in the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES.M7_CX_OPPOSITE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES', 'Chooses the opposite meaning.', '{"question":"What does the word mean in the passage.","wrong_answer":"the opposite meaning","correct_answer":"the same meaning as the clues show"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the opposite meaning" next to the right answer in a new sentence and ask again.', 'Check the words around it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES.M7_CX_WRONG_CLUE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.CONTEXT_CLUES', 'Picks words that are not a clue to the hard word.', '{"question":"Which words in the passage help you understand the word.","wrong_answer":"words unrelated to the word","correct_answer":"words that explain the word"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "words unrelated to the word" next to the right answer in a new sentence and ask again.', 'A clue explains or describes the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS.M7_FQ_NEARBY_DETAIL', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'Gives a detail that is near the answer but is not the answer.', '{"question":"Which answer is stated in the passage.","wrong_answer":"a nearby detail","correct_answer":"the exact answer"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a nearby detail" next to the right answer in a new sentence and ask again.', 'Match the question word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS.M7_FQ_OUTSIDE_KNOWLEDGE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'Uses outside knowledge that the passage does not give.', '{"question":"Which answer is stated in the passage.","wrong_answer":"something from your own knowledge","correct_answer":"what the passage says"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "something from your own knowledge" next to the right answer in a new sentence and ask again.', 'Use only the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS.M7_FQ_MISSES_STATED', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'Says a stated fact is false or not stated.', '{"question":"Is it true, false or not stated.","wrong_answer":"False or Not stated for a stated fact","correct_answer":"True"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "False or Not stated for a stated fact" next to the right answer in a new sentence and ask again.', 'Find the sentence that says it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS.M7_FQ_FALSE_AS_TRUE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'Says a false statement is true.', '{"question":"Is it true, false or not stated.","wrong_answer":"True for a false statement","correct_answer":"False"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "True for a false statement" next to the right answer in a new sentence and ask again.', 'The passage says the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS.M7_FQ_FALSE_AS_NOT_STATED', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'Says a false statement is not stated.', '{"question":"Is it true, false or not stated.","wrong_answer":"Not stated for a false statement","correct_answer":"False"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Not stated for a false statement" next to the right answer in a new sentence and ask again.', 'The passage does speak about it, and says something different.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS.M7_FQ_NOT_STATED_AS_TRUE', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.FACTUAL_QUESTIONS', 'Says a statement the passage does not mention is true or false.', '{"question":"Is it true, false or not stated.","wrong_answer":"True or False for a statement not in the passage","correct_answer":"Not stated"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "True or False for a statement not in the passage" next to the right answer in a new sentence and ask again.', 'The passage does not say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS.M7_IQ_OVERREACH', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS', 'Goes beyond the clues in the passage.', '{"question":"Which can you work out from the passage.","wrong_answer":"a claim with no clue","correct_answer":"a claim the clues support"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a claim with no clue" next to the right answer in a new sentence and ask again.', 'An inference needs a clue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS.M7_IQ_CONTRADICTS', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS', 'Gives an answer that goes against the passage.', '{"question":"Which can you work out from the passage.","wrong_answer":"a claim the passage goes against","correct_answer":"a claim that fits the passage"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a claim the passage goes against" next to the right answer in a new sentence and ask again.', 'Check the answer against the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS.M7_IQ_REPEATS_TEXT', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS', 'Copies a stated sentence as an inference.', '{"question":"Which can you work out from the passage, though it is not written.","wrong_answer":"a sentence copied from the passage","correct_answer":"something worked out from the clues"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a sentence copied from the passage" next to the right answer in a new sentence and ask again.', 'An inference is not written; it is worked out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY.M7_X_IM_SENSE_MIX', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.IMAGERY', 'Names the wrong sense for an image.', '{"question":"\"The bus horn screamed.\" Which sense?","wrong_answer":"sight","correct_answer":"hearing"}'::jsonb, 'All images are thought to be pictures.', 'Offer "sight" beside "hearing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Images can be sounds, smells and feelings too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS.M7_X_IQ_NOT_STATED', 'ENGL.G7.READIN.T13_INTENSIVE_READING_CO.INFERENCE_QUESTIONS', 'Answers "not stated" to an inference question.', '{"question":"\"She packed her bag before dawn.\" Why?","wrong_answer":"The poem does not say.","correct_answer":"She was leaving early on a journey."}'::jsonb, 'Only stated answers seem allowed.', 'Offer "The poem does not say." beside "She was leaving early on a journey." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the clues to infer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE.M7_SS_FRAGMENT', 'ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE', 'Takes a group of words with no verb or no subject for a sentence (The tall girl from Kisumu).', '{"question":"Which is a complete simple sentence.","wrong_answer":"The tall girl from Kisumu.","correct_answer":"The tall girl comes from Kisumu."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The tall girl from Kisumu." next to the right answer in a new sentence and ask again.', 'A sentence needs a subject and a verb and a complete thought.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE.M7_SS_COMPOUND', 'ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE', 'Calls a sentence with and, but or so a simple sentence.', '{"question":"Which is a simple sentence.","wrong_answer":"Kamau ran fast, but he lost the race.","correct_answer":"Kamau lost the race."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Kamau ran fast, but he lost the race." next to the right answer in a new sentence and ask again.', 'A simple sentence has one subject and one verb idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE.M7_SS_RUN_ON', 'ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE', 'Writes two sentences as one with no joining word or full stop (We arrived it was dark).', '{"question":"Which sentence is correct.","wrong_answer":"We arrived it was dark.","correct_answer":"We arrived. It was dark."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "We arrived it was dark." next to the right answer in a new sentence and ask again.', 'Each complete thought needs its own sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE.M7_SS_NOT_SENTENCE', 'ENGL.G7.GRAMMA.T13_SENTENCES_SIMPLE_SEN.SIMPLE_SENTENCE', 'Calls two words with no verb (a list) a sentence.', '{"question":"Which is a complete simple sentence.","wrong_answer":"Red apples and ripe mangoes.","correct_answer":"Red apples grow here."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Red apples and ripe mangoes." next to the right answer in a new sentence and ask again.', 'Look for a verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG.M7_PRS_PURPOSE', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG', 'Gives a wrong purpose for a praise song (to insult, to teach arithmetic).', '{"question":"What is the main purpose of a praise song.","wrong_answer":"to insult a person","correct_answer":"to honour a person for what he or she has done"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "to insult a person" next to the right answer in a new sentence and ask again.', 'A praise song honours someone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG.M7_PRS_WHO', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG', 'Mixes up the singer and the one praised.', '{"question":"Who is praised in a praise song for the winner of a race.","wrong_answer":"the singer","correct_answer":"the winner"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the singer" next to the right answer in a new sentence and ask again.', 'The singer praises someone else.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG.M7_PRS_EXAGGERATION', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG', 'Thinks praise songs must be exactly true to the last detail.', '{"question":"Why does a praise song say the runner is faster than the wind.","wrong_answer":"because it is a fact","correct_answer":"to show great admiration"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "because it is a fact" next to the right answer in a new sentence and ask again.', 'Exaggeration shows admiration.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG.M7_PRS_OCCASION', 'ENGL.G7.READIN.T13_ORAL_LITERATURE_PRAI.PRAISE_SONG', 'Names an occasion that does not suit a praise song.', '{"question":"At which occasion is a praise song most likely sung.","wrong_answer":"at a quarrel","correct_answer":"at a wedding or a victory celebration"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "at a quarrel" next to the right answer in a new sentence and ask again.', 'Praise songs are for occasions of honour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS.M7_ID_LITERAL', 'ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS', 'Reads an idiom word for word (it is raining cats and dogs means animals fall).', '{"question":"What does \"it is raining cats and dogs\" mean.","wrong_answer":"animals are falling from the sky","correct_answer":"it is raining very hard"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "animals are falling from the sky" next to the right answer in a new sentence and ask again.', 'An idiom means more than its words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS.M7_ID_WRONG_MEANING', 'ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS', 'Gives a meaning that fits one word of the idiom but not all.', '{"question":"What does \"spill the beans\" mean.","wrong_answer":"to cook a meal","correct_answer":"to tell a secret"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "to cook a meal" next to the right answer in a new sentence and ask again.', 'Think of what happens when beans spill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS.M7_ID_CHANGED_WORD', 'ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS', 'Changes a word in the idiom (a piece of pie, hit the nail on the finger).', '{"question":"Complete: It was a piece of ___. (very easy)","wrong_answer":"pie","correct_answer":"cake"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "pie" next to the right answer in a new sentence and ask again.', 'The words of an idiom are fixed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS.M7_X_ID_WRONG_SITUATION', 'ENGL.G7.WRITIN.T13_CREATIVE_WRITING_NAR.IDIOMS', 'Uses an idiom in a situation it does not fit.', '{"question":"Which fits a boy who finally finished his long project?","wrong_answer":"He spilled the beans.","correct_answer":"He saw the light at the end of the tunnel."}'::jsonb, 'Idioms are known by form, not use.', 'Offer "He spilled the beans." beside "He saw the light at the end of the tunnel." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the idiom''s meaning to the situation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS.M7_SC_F_V', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS', 'Mixes the sounds /f/ and /v/ (fan and van sound the same).', '{"question":"Which word starts with the sound /v/.","wrong_answer":"fan","correct_answer":"van"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fan" next to the right answer in a new sentence and ask again.', 'Touch your throat: /v/ shakes, /f/ does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS.M7_SC_N_NG', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS', 'Mixes the final sounds /n/ and /ŋ/ (sin and sing).', '{"question":"Which word ends with the sound /ŋ/.","wrong_answer":"sin","correct_answer":"sing"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "sin" next to the right answer in a new sentence and ask again.', 'Sing ends with the sound at the back of the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS.M7_SC_L_R', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS', 'Mixes the sounds /l/ and /r/ (light and right sound the same).', '{"question":"Which word starts with the sound /r/.","wrong_answer":"light","correct_answer":"right"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "light" next to the right answer in a new sentence and ask again.', 'For /l/ the tongue touches the top; for /r/ it does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS.M7_SC_T_D', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS', 'Mixes the sounds /t/ and /d/ (tin and din).', '{"question":"Which word starts with the sound /d/.","wrong_answer":"tin","correct_answer":"din"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "tin" next to the right answer in a new sentence and ask again.', '/d/ is voiced, /t/ is not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS.M7_SC_SPELLING', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.SOUNDS_CONSONANTS', 'Matches by the letter instead of the sound.', '{"question":"Which word ends with the sound /f/.","wrong_answer":"of","correct_answer":"laugh"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "of" next to the right answer in a new sentence and ask again.', 'Say each word. Of ends in /v/. Laugh ends in /f/.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION.M7_X_IN_WH_RISE', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION', 'Raises the voice at the end of WH questions.', '{"question":"Say: Who scored the goal?","wrong_answer":"rising at goal","correct_answer":"falling at goal"}'::jsonb, 'All questions are thought to rise.', 'Offer "rising at goal" beside "falling at goal" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'WH questions fall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION.M7_X_IN_YESNO_FLAT', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION', 'Keeps yes or no questions flat.', '{"question":"Say: Did the team win?","wrong_answer":"flat","correct_answer":"rising at win"}'::jsonb, 'Home languages mark questions with a word.', 'Offer "flat" beside "rising at win" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rise at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION.M7_X_IN_STATEMENT_QUESTION', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION', 'Turns a statement into a question only by adding a question mark, keeping a falling tune.', '{"question":"Say \"You are the captain?\" as a surprised question.","wrong_answer":"falling tune","correct_answer":"rising tune"}'::jsonb, 'The written mark is not linked to the voice.', 'Offer "falling tune" beside "rising tune" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rise to make it a question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION.M7_X_IN_TAG', 'ENGL.G7.LISTEN.T14_CONSONANT_SOUNDS_AND.INTONATION', 'Uses a rising tune on a question tag when sure.', '{"question":"You are sure. Say: It was a great match, wasn''t it?","wrong_answer":"rising on wasn''t it","correct_answer":"falling on wasn''t it"}'::jsonb, 'All tags are said like questions.', 'Offer "rising on wasn''t it" beside "falling on wasn''t it" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fall when you expect agreement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_NEAR_NOUN', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Makes the verb agree with the noun beside it, not the subject (The box of mangoes are heavy).', '{"question":"The basket of mangoes ___ heavy.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "are" next to the right answer in a new sentence and ask again.', 'The subject is the basket, one thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_PLURAL', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Uses a singular verb with a plural subject (The boys plays).', '{"question":"The boys ___ in the field.","wrong_answer":"plays","correct_answer":"play"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "plays" next to the right answer in a new sentence and ask again.', 'More than one boy takes the plain verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_SINGULAR', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Uses a plural verb with a singular subject (My sister like music).', '{"question":"My sister ___ music.","wrong_answer":"like","correct_answer":"likes"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "like" next to the right answer in a new sentence and ask again.', 'One sister takes likes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_AND_SUBJECT', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Uses a singular verb after two subjects joined by and (Juma and Otieno is friends).', '{"question":"Juma and Otieno ___ good friends.","wrong_answer":"is","correct_answer":"are"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "is" next to the right answer in a new sentence and ask again.', 'Two people joined by and take are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_FIND_SUBJECT', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Names the verb or the object as the subject.', '{"question":"What is the subject of \"The farmer sells vegetables\"","wrong_answer":"sells","correct_answer":"farmer"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "sells" next to the right answer in a new sentence and ask again.', 'The subject is who or what does the action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_EVERYONE', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Uses a plural verb with everyone, each or nobody (Everyone are ready).', '{"question":"Everyone ___ ready for the trip.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "are" next to the right answer in a new sentence and ask again.', 'Everyone means every one person, so is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT.M7_SVA_THERE_IS', 'ENGL.G7.GRAMMA.T14_SUBJECT_VERB_AGREEME.SV_AGREEMENT', 'Uses there is with a plural noun (There is three books on the table).', '{"question":"There ___ four chairs in the room.","wrong_answer":"is","correct_answer":"are"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "is" next to the right answer in a new sentence and ask again.', 'Four chairs is plural, so are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE.M7_ST_SIMILE_METAPHOR', 'ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE', 'Calls a simile a metaphor or a metaphor a simile.', '{"question":"Which is a metaphor.","wrong_answer":"He ran like the wind.","correct_answer":"Time is a thief."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "He ran like the wind." next to the right answer in a new sentence and ask again.', 'A simile uses like or as.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE.M7_ST_DIALOGUE', 'ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE', 'Does not see which part of a text is dialogue.', '{"question":"Which sentence is dialogue.","wrong_answer":"The sun rose over the hill.","correct_answer":"\"Come here,\" said Mama."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The sun rose over the hill." next to the right answer in a new sentence and ask again.', 'Dialogue is what the characters say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE.M7_ST_SIMILE_AS_LIKE', 'ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE', 'Writes as ... like or like ... as in a simile.', '{"question":"Complete: as brave ___ a lion.","wrong_answer":"like","correct_answer":"as"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "like" next to the right answer in a new sentence and ask again.', 'The pattern is as ... as.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE.M7_ST_LITERAL_METAPHOR', 'ENGL.G7.READIN.T14_FEATURES_OF_STYLE.STYLE', 'Reads a metaphor as true (the classroom was a zoo).', '{"question":"In \"the classroom was a zoo\", what does the writer mean.","wrong_answer":"there were animals in it","correct_answer":"the class was noisy and wild"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "there were animals in it" next to the right answer in a new sentence and ask again.', 'A metaphor does not mean the words literally.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES.M7_DW_NARRATIVE_DESC', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES', 'Takes a story of events for a description.', '{"question":"Which text is descriptive writing.","wrong_answer":"We walked to the lake and then swam.","correct_answer":"The lake was calm and silver, and the air smelled of wet grass."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "We walked to the lake and then swam." next to the right answer in a new sentence and ask again.', 'A description shows what something looks, sounds or feels like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES.M7_DW_FACTS_ONLY', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES', 'Thinks listing facts is a description.', '{"question":"Which sentence is the best description.","wrong_answer":"The market opens at six o''clock.","correct_answer":"The market bursts with the smell of fresh bread and the shouts of sellers."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The market opens at six o''clock." next to the right answer in a new sentence and ask again.', 'A description uses the senses: see, hear, smell, touch, taste.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES.M7_DW_ORDER', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES', 'Describes in a jumbled order.', '{"question":"In what order is a building usually described.","wrong_answer":"in any order","correct_answer":"in a clear order, such as from the front to the back"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "in any order" next to the right answer in a new sentence and ask again.', 'A reader must follow where you are looking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES.M7_DW_VAGUE_WORDS', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_FEATURES', 'Uses vague words such as nice and good instead of exact ones.', '{"question":"Which sentence has the best detail.","wrong_answer":"The food was nice.","correct_answer":"The ugali was hot and soft, with a smoke-sweet smell."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The food was nice." next to the right answer in a new sentence and ask again.', 'Exact words let the reader picture it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M7_X_DC_NARRATES', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Narrates events instead of describing.', '{"question":"Describe the football pitch.","wrong_answer":"We played a match and won.","correct_answer":"The pitch is a sea of green, its white lines fresh after the rain."}'::jsonb, 'Narrative is the most practised.', 'Offer "We played a match and won." beside "The pitch is a sea of green, its white lines fresh after the rain." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe what it is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M7_X_DC_VAGUE', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Uses vague words.', '{"question":"Improve: The crowd was nice.","wrong_answer":"The crowd was nice.","correct_answer":"The crowd roared like thunder."}'::jsonb, 'A small stock of words.', 'Offer "The crowd was nice." beside "The crowd roared like thunder." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Exact words and a simile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M7_X_DC_SHORT', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Writes far fewer than 200 words.', '{"question":"Is 90 words enough for a 200 to 240 word task?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'The child stops when the main features are named.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add a sense or a simile to each feature.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M7_X_DC_NO_ORDER', 'ENGL.G7.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Jumps around the subject.', '{"question":"Better order for describing a stadium?","wrong_answer":"seats, pitch, seats, gate","correct_answer":"gate, seats, pitch"}'::jsonb, 'Details come as remembered.', 'Offer "seats, pitch, seats, gate" beside "gate, seats, pitch" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Move through it in one direction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT.M7_OR_ORDER', 'ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT', 'Puts the parts of an oral report in the wrong order.', '{"question":"Which part of an oral report comes first.","wrong_answer":"the end of the event","correct_answer":"a greeting and what the report is about"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the end of the event" next to the right answer in a new sentence and ask again.', 'Start by saying what you will report.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT.M7_OR_OPINION', 'ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT', 'Adds one''s own opinion where only the facts are wanted.', '{"question":"Which sentence belongs in an oral report on a fire drill.","wrong_answer":"The drill was so boring.","correct_answer":"The drill began at ten o''clock and the whole school reached the field in four minutes."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The drill was so boring." next to the right answer in a new sentence and ask again.', 'A report tells what happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT.M7_OR_CLOSING', 'ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT', 'Ends a report without a closing.', '{"question":"Which sentence best closes an oral report.","wrong_answer":"And then the bell rang and","correct_answer":"That was the end of the event. Thank you for listening."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "And then the bell rang and" next to the right answer in a new sentence and ask again.', 'A closing tells the report is complete.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT.M7_OR_TENSE', 'ENGL.G7.LISTEN.T15_ORAL_REPORTS.ORAL_REPORT', 'Reports a past event in the present tense.', '{"question":"Which sentence is correct in a report on yesterday''s match.","wrong_answer":"The team win the match.","correct_answer":"The team won the match."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The team win the match." next to the right answer in a new sentence and ask again.', 'An event that has finished is reported in the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES.M7_FL_FLAT', 'ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES', 'Thinks a fluent reader reads in one even voice with no feeling.', '{"question":"Which helps you to read with expression.","wrong_answer":"reading every word in the same flat voice","correct_answer":"changing your voice to show feelings and pausing at full stops"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "reading every word in the same flat voice" next to the right answer in a new sentence and ask again.', 'Expression means the voice shows the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES.M7_FL_FAST', 'ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES', 'Thinks fluent reading is reading as fast as possible.', '{"question":"Which is reading at the right speed.","wrong_answer":"as fast as possible","correct_answer":"not too fast and not too slow, so the listener can follow"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "as fast as possible" next to the right answer in a new sentence and ask again.', 'Fluent reading can be understood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES.M7_FL_WORD', 'ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES', 'Reads one word at a time and stops at every hard word.', '{"question":"Which is a way to read more fluently.","wrong_answer":"stopping at every difficult word","correct_answer":"reading the same short text several times"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "stopping at every difficult word" next to the right answer in a new sentence and ask again.', 'Fluent reading flows in groups of words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES.M7_X_FL_NO_PREVIEW', 'ENGL.G7.READIN.T15_READING_FLUENCY.FLUENCY_STRATEGIES', 'Reads aloud without first reading silently.', '{"question":"Before reading aloud to the class, you should ...","wrong_answer":"start at once","correct_answer":"read the text silently first"}'::jsonb, 'Reading aloud is treated as a first reading.', 'Offer "start at once" beside "read the text silently first" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read silently first to plan the expression.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES.M7_NG_DOUBLE', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'Uses two negatives (I do not have no pen).', '{"question":"I do not have ___ pen.","wrong_answer":"no","correct_answer":"a"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "no" next to the right answer in a new sentence and ask again.', 'One negative is enough: do not have a pen, or have no pen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES.M7_NG_DONT_THIRD', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'Uses don''t after he, she or it (She don''t like beans).', '{"question":"She ___ like beans.","wrong_answer":"don''t","correct_answer":"doesn''t"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "don''t" next to the right answer in a new sentence and ask again.', 'One person takes does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES.M7_NG_DID_PAST', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'Uses did not with the past form (She did not went).', '{"question":"He did not ___ to school yesterday.","wrong_answer":"went","correct_answer":"go"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "went" next to the right answer in a new sentence and ask again.', 'After did not the plain verb is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES.M7_NG_NOT_PLACE', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'Puts not in the wrong place (I am go not).', '{"question":"Which sentence is negative and correct.","wrong_answer":"She not is here.","correct_answer":"She is not here."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She not is here." next to the right answer in a new sentence and ask again.', 'Not follows is, are, was, were, can, will, or do/does/did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES.M7_NG_NO_NOT', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'Uses no where not is needed, or not where no is needed (I am no tired).', '{"question":"I am ___ tired.","wrong_answer":"no","correct_answer":"not"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "no" next to the right answer in a new sentence and ask again.', 'Not goes with a verb or an adjective. No goes with a noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES.M7_NG_KIND', 'ENGL.G7.GRAMMA.T15_AFFIRMATIVE_AND_NEGA.NEGATIVES', 'Calls a negative sentence affirmative, or the other way, when no not appears (Nobody came).', '{"question":"Which sentence is negative.","wrong_answer":"Everybody came.","correct_answer":"Nobody came."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Everybody came." next to the right answer in a new sentence and ask again.', 'Nobody means not anybody.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_POETRY.POEM_MEANING.M7_PM_DETAIL_SUBJECT', 'ENGL.G7.READIN.T15_POETRY.POEM_MEANING', 'Takes a detail for the subject of the poem.', '{"question":"What is the poem mainly about.","wrong_answer":"a bird on a branch","correct_answer":"the beauty of the morning"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a bird on a branch" next to the right answer in a new sentence and ask again.', 'The subject is what the whole poem is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_POETRY.POEM_MEANING.M7_PM_NO_MESSAGE', 'ENGL.G7.READIN.T15_POETRY.POEM_MEANING', 'Thinks a poem has no message.', '{"question":"What message does the poet want to pass on.","wrong_answer":"there is no message","correct_answer":"we should look after our environment"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "there is no message" next to the right answer in a new sentence and ask again.', 'Ask: what does the poet want us to think about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_POETRY.POEM_MEANING.M7_PM_LITERAL', 'ENGL.G7.READIN.T15_POETRY.POEM_MEANING', 'Reads a line word for word where it means more.', '{"question":"In a poem, \"the sun smiled on the fields\". What does it mean.","wrong_answer":"the sun had a mouth","correct_answer":"the sunshine was warm and kind"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the sun had a mouth" next to the right answer in a new sentence and ask again.', 'The poet pictures the sun as a person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.READIN.T15_POETRY.POEM_MEANING.M7_PM_NOT_IN_POEM', 'ENGL.G7.READIN.T15_POETRY.POEM_MEANING', 'Brings in an idea that is not in the poem.', '{"question":"Which message does the poem teach.","wrong_answer":"a message the poem does not hold","correct_answer":"a message the lines support"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a message the poem does not hold" next to the right answer in a new sentence and ask again.', 'Check the idea against the lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER.M7_NO_MISSING_WHEN', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER', 'Leaves out the date or time of a notice.', '{"question":"This notice has a heading, the place and the writer. What is missing: \"SPORTS DAY. At the school field. Games Master.\"","wrong_answer":"a picture","correct_answer":"the date and time"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a picture" next to the right answer in a new sentence and ask again.', 'A notice must say when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER.M7_NO_POSTER_LONG', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER', 'Writes a poster in long paragraphs.', '{"question":"Which is best for a poster.","wrong_answer":"a long paragraph with every detail","correct_answer":"a big heading and a few short lines"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a long paragraph with every detail" next to the right answer in a new sentence and ask again.', 'A poster must be read at a glance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER.M7_NO_NOTICE_POSTER', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER', 'Mixes up the features of a notice and a poster.', '{"question":"Which has a picture to catch the eye.","wrong_answer":"a notice","correct_answer":"a poster"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a notice" next to the right answer in a new sentence and ask again.', 'A poster uses a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER.M7_NO_SIGNED', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_POSTER', 'Forgets who wrote the notice.', '{"question":"Who signs a school notice.","wrong_answer":"nobody","correct_answer":"the person who wrote it, with the date"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "nobody" next to the right answer in a new sentence and ask again.', 'A reader must know who to ask.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN.M7_X_ND_NO_DETAILS', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN', 'Leaves out when or where.', '{"question":"A notice about a clean-up: what must it include?","wrong_answer":"a picture","correct_answer":"the date, time and place"}'::jsonb, 'The writer knows the details.', 'Offer "a picture" beside "the date, time and place" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check what, when, where, who.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN.M7_X_ND_POSTER_TEXT_HEAVY', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN', 'Fills a poster with long paragraphs.', '{"question":"Which is a better poster?","wrong_answer":"a page of small writing","correct_answer":"a big heading, few words and a picture"}'::jsonb, 'A poster is treated like an essay.', 'Offer "a page of small writing" beside "a big heading, few words and a picture" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Few words, big heading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN.M7_X_ND_UNSIGNED', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN', 'Leaves the notice unsigned and undated.', '{"question":"What goes at the bottom of a notice?","wrong_answer":"nothing","correct_answer":"the name and title of the writer, and the date"}'::jsonb, 'Who wrote it seems obvious.', 'Offer "nothing" beside "the name and title of the writer, and the date" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sign and date it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN.M7_X_ND_NO_ACTION', 'ENGL.G7.WRITIN.T15_FUNCTIONAL_WRITING_N.NOTICE_DESIGN', 'Does not tell readers what to do.', '{"question":"Poster: \"Drugs are bad.\" What is missing?","wrong_answer":"nothing","correct_answer":"a call to action: Say no to drugs; call 1192 for help"}'::jsonb, 'The message stops at the problem.', 'Offer "nothing" beside "a call to action: Say no to drugs; call 1192 for help" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell readers what to do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
